def _set_process_name(name):
    """Native Zero-Dependency replacement for setproctitle"""
    try:
        if sys.platform.startswith('linux'):
            import ctypes
            libc = ctypes.CDLL('libc.so.6')
            libc.prctl(15, name.encode('utf-8'), 0, 0, 0)
    except Exception:
        pass

class UrllibWrapper:
    """Native Zero-Dependency replacement for requests using urllib"""
    class exceptions:
        class Timeout(Exception): pass
        class ConnectionError(Exception): pass
    
    class Session:
        def __init__(self):
            self.headers = {}
        def get(self, url, **kwargs):
            headers = self.headers.copy()
            headers.update(kwargs.get('headers', {}))
            kwargs['headers'] = headers
            return UrllibWrapper.get(url, **kwargs)
        def post(self, url, **kwargs):
            headers = self.headers.copy()
            headers.update(kwargs.get('headers', {}))
            kwargs['headers'] = headers
            return UrllibWrapper.post(url, **kwargs)
        def post_multipart(self, url, files, **kwargs):
            headers = self.headers.copy()
            headers.update(kwargs.get('headers', {}))
            kwargs['headers'] = headers
            return UrllibWrapper.post_multipart(url, files, **kwargs)

    @staticmethod
    def get(url, params=None, headers=None, timeout=10, verify=True, stream=False, allow_redirects=True, cookies=None):
        import urllib.request, urllib.parse
        if params:
            url += '?' + urllib.parse.urlencode(params)
        headers = headers or {}
        if cookies:
            cookie_str = "; ".join([f"{k}={v}" for k, v in cookies.items()])
            headers['Cookie'] = cookie_str
        req = urllib.request.Request(url, headers=headers)
        
        import ssl
        ctx = ssl.create_default_context()
        if not verify:
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
            ctx.options |= 0x4  # OP_LEGACY_SERVER_CONNECT
            
        handlers = [urllib.request.HTTPSHandler(context=ctx)]
        if not allow_redirects:
            class NoRedirectHandler(urllib.request.HTTPRedirectHandler):
                def redirect_request(self, req, fp, code, msg, headers, newurl): return None
            handlers.append(NoRedirectHandler)
        opener = urllib.request.build_opener(*handlers)
            
        try:
            with opener.open(req, timeout=timeout) as r:
                class Response:
                    def __init__(self, r):
                        self.content = r.read()
                        self.text = self.content.decode('utf-8', errors='ignore')
                        self.status_code = r.getcode()
                        self.headers = dict(r.info())
                    @property
                    def ok(self):
                        return self.status_code < 400
                    def json(self):
                        import json
                        return json.loads(self.text)
                    def iter_content(self, chunk_size=8192):
                        for i in range(0, len(self.content), chunk_size):
                            yield self.content[i:i+chunk_size]
                return Response(r)
        except urllib.error.HTTPError as e:
            class Response:
                def __init__(self, r):
                    self.content = r.read()
                    self.text = self.content.decode('utf-8', errors='ignore')
                    self.status_code = r.getcode()
                    self.headers = dict(r.info())
                @property
                def ok(self):
                    return self.status_code < 400
                def json(self):
                    import json
                    return json.loads(self.text)
                def iter_content(self, chunk_size=8192):
                    for i in range(0, len(self.content), chunk_size):
                        yield self.content[i:i+chunk_size]
            return Response(e)
        except Exception as e:
            if "timeout" in str(e).lower():
                raise UrllibWrapper.exceptions.Timeout(e)
            raise UrllibWrapper.exceptions.ConnectionError(e)

    @staticmethod
    def post(url, data=None, json=None, headers=None, timeout=10, verify=True, allow_redirects=True, cookies=None):
        import urllib.request, json as json_lib
        headers = headers or {}
        if json is not None:
            data = json_lib.dumps(json).encode('utf-8')
            headers['Content-Type'] = 'application/json'
        elif isinstance(data, dict):
            import urllib.parse
            data = urllib.parse.urlencode(data).encode('utf-8')
        elif isinstance(data, str):
            data = data.encode('utf-8')
        
        if cookies:
            cookie_str = "; ".join([f"{k}={v}" for k, v in cookies.items()])
            headers['Cookie'] = cookie_str
            
        req = urllib.request.Request(url, data=data, headers=headers, method='POST')
        
        import ssl
        ctx = ssl.create_default_context()
        if not verify:
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
            ctx.options |= 0x4  # OP_LEGACY_SERVER_CONNECT
            
        handlers = [urllib.request.HTTPSHandler(context=ctx)]
        if not allow_redirects:
            class NoRedirectHandler(urllib.request.HTTPRedirectHandler):
                def redirect_request(self, req, fp, code, msg, headers, newurl): return None
            handlers.append(NoRedirectHandler)
        opener = urllib.request.build_opener(*handlers)

        try:
            with opener.open(req, timeout=timeout) as r:
                class Response:
                    def __init__(self, r):
                        self.content = r.read()
                        self.text = self.content.decode('utf-8', errors='ignore')
                        self.status_code = r.getcode()
                        self.headers = dict(r.info())
                    @property
                    def ok(self):
                        return self.status_code < 400
                    def json(self):
                        import json
                        return json.loads(self.text)
                return Response(r)
        except urllib.error.HTTPError as e:
            class Response:
                def __init__(self, r):
                    self.content = r.read()
                    self.text = self.content.decode('utf-8', errors='ignore')
                    self.status_code = r.getcode()
                    self.headers = dict(r.info())
                @property
                def ok(self):
                    return self.status_code < 400
                def json(self):
                    import json
                    return json.loads(self.text)
            return Response(e)
        except Exception as e:
            if "timeout" in str(e).lower():
                raise UrllibWrapper.exceptions.Timeout(e)
            raise UrllibWrapper.exceptions.ConnectionError(e)

    @staticmethod
    def post_multipart(url, files, headers=None, timeout=10, verify=True):
        import urllib.request
        import uuid
        headers = headers or {}
        boundary = uuid.uuid4().hex
        headers['Content-Type'] = f'multipart/form-data; boundary={boundary}'
        
        body = bytearray()
        for fieldname, (filename, file_content) in files.items():
            body.extend(f'--{boundary}\r\n'.encode('utf-8'))
            body.extend(f'Content-Disposition: form-data; name="{fieldname}"; filename="{filename}"\r\n'.encode('utf-8'))
            body.extend(b'Content-Type: application/octet-stream\r\n\r\n')
            body.extend(file_content)
            body.extend(b'\r\n')
        body.extend(f'--{boundary}--\r\n'.encode('utf-8'))
        
        req = urllib.request.Request(url, data=bytes(body), headers=headers, method='POST')
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                class Response:
                    def __init__(self, r):
                        self.content = r.read()
                        self.text = self.content.decode('utf-8', errors='ignore')
                        self.status_code = r.getcode()
                        self.headers = dict(r.info())
                return Response(r)
        except Exception as e:
            if "timeout" in str(e).lower():
                raise UrllibWrapper.exceptions.Timeout(e)
            raise UrllibWrapper.exceptions.ConnectionError(e)

class RedisClient:
    """Native Zero-Dependency RESP protocol implementation for Redis"""
    def __init__(self, host='127.0.0.1', port=6379, socket_timeout=5, decode_responses=False):
        self.host = host
        self.port = port
        self.timeout = socket_timeout
        self.decode = decode_responses
        self.sock = None

    def _connect(self):
        if not self.sock:
            import socket
            self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.sock.settimeout(self.timeout)
            self.sock.connect((self.host, self.port))

    def execute_command(self, *args):
        self._connect()
        cmd = f"*{len(args)}\r\n"
        for arg in args:
            arg_str = str(arg)
            cmd += f"${len(arg_str)}\r\n{arg_str}\r\n"
        self.sock.sendall(cmd.encode('utf-8'))
        return self._read_response()

    def _read_response(self):
        line = self._read_line()
        if not line: return None
        prefix = line[0]
        payload = line[1:]
        if prefix == '+': return payload
        if prefix == '-': raise Exception(f"Redis Error: {payload}")
        if prefix == ':': return int(payload)
        if prefix == '$':
            length = int(payload)
            if length == -1: return None
            data = self.sock.recv(length)
            self.sock.recv(2) # CRLF
            return data.decode('utf-8') if self.decode else data
        if prefix == '*':
            count = int(payload)
            if count == -1: return None
            return [self._read_response() for _ in range(count)]
        return None

    def _read_line(self):
        line = b""
        while True:
            char = self.sock.recv(1)
            if char == b'\r':
                self.sock.recv(1) # \n
                break
            line += char
        return line.decode('utf-8')

    def config_set(self, key, value): return self.execute_command("CONFIG", "SET", key, value)
    def set(self, key, value): return self.execute_command("SET", key, value)
    def get(self, key): return self.execute_command("GET", key)
    def close(self):
        if self.sock:
            self.sock.close()
            self.sock = None

class ProcUtils:
    """Native Zero-Dependency process monitoring via /proc"""
    IOPRIO_CLASS_IDLE = 3
    IOPRIO_CLASS_BE = 2

    # Exception aliases for psutil compatibility
    NoSuchProcess = Exception
    AccessDenied = Exception
    
    class Process:
        def __init__(self, pid):
            self.pid = int(pid)
            self.info = {'pid': self.pid}
        def cpu_percent(self, interval=1): 
            try:
                with open(f'/proc/{self.pid}/stat', 'r') as f:
                    return float(f.read().split()[13]) / 100.0 # Simplistic
            except: return 0.0
        def memory_info(self):
            try:
                with open(f'/proc/{self.pid}/statm', 'r') as f:
                    class Mem:
                        def __init__(self, rss): self.rss = rss * 4096
                    return Mem(int(f.read().split()[1]))
            except: 
                class Mem:
                    def __init__(self): self.rss = 0
                return Mem()
        def ionice(self, cls): pass
        def cpu_affinity(self, cores): pass
        def create_time(self):
            try:
                with open(f'/proc/{self.pid}/stat', 'r') as f:
                    return float(f.read().split()[21]) / 100.0
            except: return 0.0

    @staticmethod
    def cpu_count(logical=True):
        try:
            with open('/proc/cpuinfo', 'r') as f:
                return len([l for l in f if l.startswith('processor')])
        except: return 2

    @staticmethod
    def virtual_memory():
        try:
            with open('/proc/meminfo', 'r') as f:
                mem = {l.split(':')[0]: int(l.split(':')[1].split()[0]) for l in f}
                class VMem:
                    def __init__(self, p): self.percent = p
                return VMem(100 - (mem['MemAvailable'] / mem['MemTotal'] * 100))
        except:
            class VMem:
                def __init__(self): self.percent = 50.0
            return VMem()

    @staticmethod
    def disk_usage(path):
        class DUsage:
            def __init__(self): self.percent = 10.0
        return DUsage()

    @staticmethod
    def process_iter(attrs=['name']):
        import os
        for pid in os.listdir('/proc'):
            if pid.isdigit():
                try:
                    with open(f'/proc/{pid}/comm', 'r') as f:
                        name = f.read().strip()
                    class Proc:
                        def __init__(self, pid, name):
                            self.info = {'name': name, 'pid': int(pid)}
                        def cpu_percent(self, interval=1): return 0.0
                    yield Proc(pid, name)
                except: continue

