# distro removed â€” stdlib-only implementation (reads /etc/os-release directly)
class distro:
    """Zero-dependency distro detection via /etc/os-release"""
    @staticmethod
    def id():
        try:
            with open('/etc/os-release') as _f:
                for _line in _f:
                    if _line.startswith('ID='):
                        return _line.split('=', 1)[1].strip().strip('"').lower()
        except OSError:
            pass
        # Fallback: check marker files
        if os.path.exists('/etc/debian_version'):
            return 'ubuntu'
        if os.path.exists('/etc/redhat-release'):
            return 'centos'
        return 'linux'


