    def start_monitoring(self, interval=300):
        """5min health checks + auto-restart"""
        if self.monitoring_active:
            return
        
        self.monitoring_active = True
        
        def monitor_loop():
            import asyncio
            
            async def _run_checks():
                dead_miners = await self._health_check_instances()
                await self._restart_dead_miners(dead_miners)
                
                # Wallet rotation sync
                if self.wallet_manager and self.wallet_manager.should_rotate():
                    new_wallet = self.wallet_manager.get_next_wallet()
                    await self._rotate_all_wallets(new_wallet)

            while self.monitoring_active:
                try:
                    try:
                        loop = asyncio.get_running_loop()
                        future = asyncio.run_coroutine_threadsafe(_run_checks(), loop)
                        future.result()
                    except RuntimeError:
                        asyncio.run(_run_checks())
                    
                    time.sleep(interval)
                except Exception as e:
                    self.logger.error(f"Monitor error: {e}")
                    time.sleep(60)
        
        threading.Thread(target=monitor_loop, daemon=True).start()
        self.logger.info("â›ï¸  Cloud mining monitoring started")
    
    async def _health_check_instances(self):
        """Check 10% sample for hashrate using asyncssh"""
        import asyncio
        dead = []
        with self.stats_lock:
            running_ips = [ip for ip, status in self.instances.items() if status['status'] == 'running']
            sample_size = min(500, len(running_ips) // 10)
            sample_ips = running_ips[:sample_size]
        
        if not sample_ips:
            return dead
            
        tasks = [self._check_single_instance(ip) for ip in sample_ips]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        
        for ip, res in zip(sample_ips, results):
            if isinstance(res, Exception) or not res[0]:
                dead.append(ip)
            else:
                alive, hashrate = res
                with self.stats_lock:
                    self.instances[ip]['hashrate'] = hashrate
                    self.mining_stats['total_hashrate'] += hashrate
        
        return dead
    
    async def _check_single_instance(self, ip):
        """SSH health check + hashrate via asyncssh"""
        import asyncssh
        try:
            async with asyncssh.connect(ip, username='ec2-user', known_hosts=None, client_keys=None) as conn:
                # Process check
                result = await conn.run("ps aux | grep xmrig | grep -v grep | wc -l", check=False)
                alive = int(result.stdout.strip()) > 0 if result.stdout else False
                
                # Hashrate from log
                if alive:
                    res_log = await conn.run("tail -20 /var/log/cloudminer.log | grep -i speed", check=False)
                    log = res_log.stdout if res_log.stdout else ""
                    hashrate_match = re.search(r'(\d+\.?\d*)\s*(?:[kMGT]?H)', log)
                    hashrate = float(hashrate_match.group(1)) if hashrate_match else 0.0
                    
                    # Unit conversion
                    if 'kH' in log: hashrate *= 1000
                    elif 'MH' in log: hashrate *= 1000000
                    elif 'GH' in log: hashrate *= 1000000000
                else:
                    hashrate = 0.0
                
                return alive, hashrate / 1e9  # GH/s
                
        except Exception:
            return False, 0.0
    
    async def _restart_dead_miners(self, dead_ips):
        """Auto-restart using asyncssh"""
        import asyncio
        import asyncssh
        
        async def _restart_single(ip):
            try:
                async with asyncssh.connect(ip, username='ec2-user', known_hosts=None, client_keys=None) as conn:
                    await conn.run("sudo pkill -f xmrig", check=False)
                    await asyncio.sleep(2)
                    await conn.run("sudo /opt/start_miner.sh", check=False)
                    
                    with self.stats_lock:
                        self.instances[ip]['restart_count'] = self.instances[ip].get('restart_count', 0) + 1
                        self.mining_stats['restarts'] += 1
                    return True
            except Exception:
                return False

        if not dead_ips:
            return

        tasks = [_restart_single(ip) for ip in dead_ips[:100]] # Limit burst
        results = await asyncio.gather(*tasks, return_exceptions=True)
        restarts = sum(1 for r in results if r is True)
        
        self.logger.info(f"ðŸ”„ Restarted {restarts}/{len(dead_ips)} dead miners")
    
    async def _rotate_all_wallets(self, new_wallet):
        """Sync wallet rotation via asyncssh"""
        import asyncio
        import asyncssh
        
        async def _rotate_single(ip):
            try:
                async with asyncssh.connect(ip, username='ec2-user', known_hosts=None, client_keys=None) as conn:
                    cmd = f"sudo sed -i 's/\\\"user\\\": \\\".*\\\"/\\\"user\\\": \\\"{new_wallet}\\\"/' /opt/config.json"
                    res = await conn.run(cmd, check=False)
                    if res.exit_status == 0:
                        await conn.run("sudo pkill -f xmrig && sleep 2 && sudo /opt/start_miner.sh", check=False)
                        return True
            except Exception:
                pass
            return False

        running_ips = [ip for ip, status in self.instances.items() if status['status'] == 'running']
        if not running_ips:
            return
            
        tasks = [_rotate_single(ip) for ip in running_ips[:200]] # Batch limit
        results = await asyncio.gather(*tasks, return_exceptions=True)
        updated = sum(1 for r in results if r is True)
        
        self.logger.info(f"ðŸ’° Wallet rotated: {updated} miners")
    
