class SafeOperation:
    """Decorator for safe operation execution with proper error handling and validation"""
    
    # âœ… VALIDATION: Define valid log levels
    VALID_LOG_LEVELS = {'debug', 'info', 'warning', 'error', 'critical'}
    
    @staticmethod
    def safe_operation(operation_name, log_level="error", reraise=False):
        """Decorator for safe operation execution with validation"""
        
        # âœ… VALIDATE log_level parameter
        if log_level not in SafeOperation.VALID_LOG_LEVELS:
            logger.warning(f"âŒ Invalid log_level '{log_level}', defaulting to 'error'")
            log_level = "error"  # Safe default
        
        def decorator(func):
            def wrapper(*args, **kwargs):
                try:
                    return func(*args, **kwargs)
                    
                # âœ… SPECIFIC ERROR HANDLING - NO MORE GENERIC CATCH-ALL
                except subprocess.TimeoutExpired as e:
                    error_msg = f"âŒ TIMEOUT in {operation_name}: {e.cmd} exceeded {e.timeout}s"
                    log_func = getattr(logger, log_level, logger.error)  # âœ… VALIDATED
                    log_func(error_msg)
                    if reraise: 
                        raise
                    return None
                    
                except subprocess.CalledProcessError as e:
                    error_msg = f"âŒ COMMAND FAILED in {operation_name}: Return code {e.returncode}"
                    log_func = getattr(logger, log_level, logger.error)  # âœ… VALIDATED
                    log_func(error_msg)
                    if e.stderr:
                        stderr_preview = e.stderr.decode()[:200] if isinstance(e.stderr, bytes) else str(e.stderr)[:200]
                        log_func(f"   Stderr: {stderr_preview}")
                    if reraise: 
                        raise
                    return None
                    
                except OSError as e:
                    error_msg = f"âŒ SYSTEM ERROR in {operation_name}: {e.strerror}"
                    log_func = getattr(logger, log_level, logger.error)  # âœ… VALIDATED
                    log_func(error_msg)
                    if reraise: 
                        raise
                    return None
                    
                except json.JSONDecodeError as e:
                    error_msg = f"âŒ JSON ERROR in {operation_name}: {e.msg} at line {e.lineno}"
                    log_func = getattr(logger, log_level, logger.error)  # âœ… VALIDATED
                    log_func(error_msg)
                    if reraise: 
                        raise
                    return None
                    
                except redis.exceptions.ConnectionError as e:
                    error_msg = f"âŒ REDIS CONNECTION ERROR in {operation_name}: {e}"
                    log_func = getattr(logger, log_level, logger.error)  # âœ… VALIDATED
                    log_func(error_msg)
                    if reraise: 
                        raise
                    return None
                    
                except redis.exceptions.AuthenticationError as e:
                    error_msg = f"âŒ REDIS AUTH ERROR in {operation_name}: {e}"
                    log_func = getattr(logger, log_level, logger.error)  # âœ… VALIDATED
                    log_func(error_msg)
                    if reraise: 
                        raise
                    return None
                    
                except FileNotFoundError as e:
                    error_msg = f"âŒ FILE NOT FOUND in {operation_name}: {e}"
                    log_func = getattr(logger, log_level, logger.error)  # âœ… VALIDATED
                    log_func(error_msg)
                    if reraise: 
                        raise
                    return None
                    
                except PermissionError as e:
                    error_msg = f"âŒ PERMISSION DENIED in {operation_name}: {e}"
                    log_func = getattr(logger, log_level, logger.error)  # âœ… VALIDATED
                    log_func(error_msg)
                    if reraise: 
                        raise
                    return None
                    
                except MemoryError as e:
                    error_msg = f"âŒ MEMORY ERROR in {operation_name}: {e}"
                    log_func = getattr(logger, log_level, logger.critical)  # âœ… Always critical
                    log_func(error_msg)
                    raise  # Always reraise memory errors
                    
                except Exception as e:
                    error_msg = f"âŒ UNEXPECTED {type(e).__name__} in {operation_name}: {e}"
                    log_func = getattr(logger, log_level, logger.error)  # âœ… VALIDATED
                    log_func(error_msg)
                    if reraise: 
                        raise
                    return None
                    
            return wrapper
        return decorator

    @classmethod
    def validate_configuration(cls):
        """âœ… Validate that SafeOperation is properly configured"""
        issues = []
        
        # Check that all log levels are valid
        for level in cls.VALID_LOG_LEVELS:
            if not hasattr(logger, level):
                issues.append(f"Logger missing level: {level}")
        
        # Check that we can actually log
        try:
            logger.debug("SafeOperation configuration test - debug")
            logger.info("SafeOperation configuration test - info")
            logger.warning("SafeOperation configuration test - warning")
            logger.error("SafeOperation configuration test - error")
            logger.critical("SafeOperation configuration test - critical")
        except Exception as e:
            issues.append(f"Logger test failed: {e}")
        
        if issues:
            logger.error(f"SafeOperation configuration issues: {issues}")
            return False
        else:
            logger.debug("âœ… SafeOperation configuration validated")
            return True

