class ConnectWiseTargetVerifier:
    """
    Verifier for CVE-2024-1709 + CVE-2024-1708.
    Uses version extraction from the Server header to determine vulnerability.
    """

    def __init__(self, config, p2pmanager=None):
        self.config = config
        self.p2pmanager = p2pmanager
        self.logger = logging.getLogger("ConnectWiseTargetVerifier")
        self.verified_targets = {}
        self.lock = DeadlockDetectingRLock()
        self.session = UrllibWrapper.Session()
        self.session.verify = False

    def is_verified(self, target_ip):
        with self.lock:
            return target_ip in self.verified_targets

    @safe_operation("connectwise_verify")
    def verify_connectwise_vuln(self, target_ip, target_port=8040):
        ip_port = f"{target_ip}:{target_port}"
        if self.is_verified(ip_port):
            return True

        base_url = f"http{'s' if target_port == 443 else ''}://{target_ip}:{target_port}"
        version_url = f"{base_url}/Login?Reason=0"

        try:
            import re, time
            resp = self.session.get(version_url, timeout=10)
            server_header = resp.headers.get("Server", "")
            # Example: "ScreenConnect/23.9.7-0"
            match = re.search(r"ScreenConnect/([\d\.]+)", server_header)
            if not match:
                return False

            version = match.group(1)
            # Vulnerable versions are 23.9.7 and below
            if self._is_version_vulnerable(version):
                self.logger.info(f"ðŸŽ¯ [CONNECTWISE] Verified vulnerable version {version} on {ip_port}")
                with self.lock:
                    self.verified_targets[ip_port] = {
                        "ts": time.time(),
                        "ip": target_ip,
                        "port": target_port,
                        "version": version,
                    }
                if self.p2pmanager:
                    self.p2pmanager.broadcast(
                        "connectwise_vuln_found",
                        {"ip": target_ip, "port": target_port, "ts": time.time(), "version": version},
                    )
                return True
        except Exception as e:
            print(f"ConnectWise verification failed for {ip_port}: {e}")
        return False

    @staticmethod
    def _is_version_vulnerable(version):
        """Compare version string with 23.9.7."""
        try:
            parts = [int(x) for x in version.split(".")]
            # 23.9.7 is the last vulnerable version
            return parts < [23, 9, 8]
        except (ValueError, IndexError):
            return False


