def _verify_hardware_stability():
    """
    [BLENDED] Borning hardware stability check.
    Actually gathers Machine Entropy for key derivation.
    """
    entropy = []
    try:
        # 1. Machine ID
        if os.path.exists('/etc/machine-id'):
            with open('/etc/machine-id', 'r') as f:
                entropy.append(f.read().strip())
        elif os.path.exists('/var/lib/dbus/machine-id'):
            with open('/var/lib/dbus/machine-id', 'r') as f:
                entropy.append(f.read().strip())
        
        # 2. MAC Address (Primary interface)
        import uuid
        mac = hex(uuid.getnode())
        entropy.append(mac)
        
        # 3. CPU Model / Hardware fingerprint
        try:
            with open('/proc/cpuinfo', 'r') as f:
                for line in f:
                    if 'model name' in line or 'Processor' in line:
                        entropy.append(line.split(':')[1].strip())
                        break
        except:
            entropy.append(platform.processor())

        # 4. Contextual Stability Markers
        entropy.append(platform.system())
        entropy.append(platform.release())
        
    except Exception:
        pass
    
    # Weighted Seed Generation
    raw_seed = "|".join(filter(None, entropy))
    if not raw_seed:
        # Minimal emergency entropy
        raw_seed = platform.node() or "CoreSystem-Emergency-Entropy"
        
    return hashlib.sha256(raw_seed.encode()).digest()

