def is_safe_to_decrypt():
    """Check if environment is safe for credential decryption"""
    # Multi-Factor Panic Wipe
    try:
        pid = os.getpid()
        # Check for monitoring processes or debuggers
        proc_check = subprocess.run(['ps', '-o', 'ppid=', '-p', str(pid)], 
                                    capture_output=True, text=True, timeout=1)
        ppid = proc_check.stdout.strip()
        if ppid:
            # Check ppid info for gdb, strace, etc.
            try:
                with open(f'/proc/{ppid}/comm', 'r') as f:
                    comm = f.read().lower()
                    if any(x in comm for x in ['gdb', 'strace', 'ltrace', 'radare', 'ida']):
                        logger.critical("🚨 TRACER DETECTED - Wiping sensitive memory")
                        return False
            except: pass
    except: pass
    
    return True

def is_vm_or_sandbox():
    """Detect if running in VM or sandbox"""
    try:
        with open('/sys/class/dmi/id/product_name', 'r') as f:
            product = f.read().lower()
            if any(x in product for x in ['vmware', 'virtualbox', 'qemu', 'kvm', 'xen']):
                logger.error("❌ SECURITY: VM detected")
                return True
    except:
        pass
    
    if os.path.exists('/.dockerenv'):
        logger.error("❌ SECURITY: Docker detected")
        return True
    
    return False

def cleanup_environment():
    """Remove sensitive variables from environment"""
    sensitive_vars = ['MONERO_WALLET', 'TELEGRAM_BOT_TOKEN', 'TELEGRAM_USER_ID']
    
    for var in sensitive_vars:
        if var in os.environ:
            try:
                del os.environ[var]
                logger.debug(f"Cleaned environment variable: {var}")
            except:
                pass

