    def _get_seed_ip(self):
        providers = ['https://api.ipify.org', 'https://ident.me', 'https://checkip.amazonaws.com']
        for url in providers:
            try:
                with urllib.request.urlopen(url, timeout=5) as resp:
                    return resp.read().decode('utf-8').strip()
            except: continue
        return "127.0.0.1"

    def _build_resp(self, *args):
        """Construct a raw RESP (REdis Serialization Protocol) array.
        
        âœ… FIXED: Type-checks for bytes vs str to prevent binary payload corruption.
        str(b"payload") would produce the literal string "b'payload'" which corrupts
        binary .so payloads and encoded Lua scripts. Length is calculated on the
        final byte representation, not Python string characters.
        """
        resp = bytearray(f"*{len(args)}\r\n".encode('utf-8'))
        for arg in args:
            if isinstance(arg, bytes):
                # Binary data (e.g., .so payloads) â€” use raw bytes directly
                resp.extend(f"${len(arg)}\r\n".encode('utf-8') + arg + b"\r\n")
            else:
                # String/int â€” encode to UTF-8 bytes for accurate length
                arg_bytes = str(arg).encode('utf-8')
                resp.extend(f"${len(arg_bytes)}\r\n".encode('utf-8') + arg_bytes + b"\r\n")
        return bytes(resp)

    async def _send_resp_command(self, reader, writer, *args):
        """Send a raw RESP command and return the decoded response"""
        try:
            writer.write(self._build_resp(*args))
            await writer.drain()
            data = await asyncio.wait_for(reader.read(8192), timeout=5)
            return data.decode('utf-8', errors='ignore')
        except:
            return None

