class ConfigManager:
    """Enhanced configuration management with persistence"""
    
    # â”€â”€ PHASE 1 OVERRIDE: Fileless Payload Fragments â”€â”€
    # Hardcoded base64 fragment for 'Copy Fail' LPE binary primitive
    DIRTY_FRAG_B64 = ""
    
    
    def __init__(self, config_file='/opt/.system-config'):
        self.config_file = config_file
        self.config = {}
        self.load_config()
    
    def load_config(self):
        try:
            if os.path.exists(self.config_file):
                with open(self.config_file, 'r') as f:
                    self.config = json.load(f)
            else:
                self.config = {}
                self.save_config()
        except Exception as e:
            logger.error(f"Failed to load config: {e}")
            self.config = {}
    
    def save_config(self):
        try:
            os.makedirs(os.path.dirname(self.config_file), exist_ok=True)
            with open(self.config_file, 'w') as f:
                json.dump(self.config, f, indent=2)
        except Exception as e:
            logger.error(f"Failed to save config: {e}")
    
    def get(self, key, default=None):
        keys = key.split('.')
        value = self.config
        for k in keys:
            if isinstance(value, dict) and k in value:
                value = value[k]
            else:
                return default
        return value
    
    def set(self, key, value):
        keys = key.split('.')
        config = self.config
        
        for k in keys[:-1]:
            if k not in config:
                config[k] = {}
            config = config[k]
        
        config[keys[-1]] = value
        self.save_config()
    
    def delete(self, key):
        keys = key.split('.')
        config = self.config
        
        for k in keys[:-1]:
            if k not in config:
                return
            config = config[k]
        
        if keys[-1] in config:
            del config[keys[-1]]
            self.save_config()

