class ApacheTargetVerifier:
    def __init__(self, configmanager, p2pmanager=None, logger=None):
        self.configmanager = configmanager
        self.p2pmanager = p2pmanager
        self.logger = logger or logging.getLogger("Internal.System.Core.apache_verifier")
        self.lock = DeadlockDetectingRLock(name="ApacheTargetVerifier.lock")
        self.verified_targets = {}

    def is_verified(self, ip, port):
        with self.lock:
            cache_key = f"{ip}:{port}"
            if cache_key in self.verified_targets:
                return (time.time() - self.verified_targets[cache_key]['ts']) < 86400
        return False

    def _send_raw_http(self, ip, port, path, method="GET", data=None):
        import http.client
        import ssl
        try:
            context = None
            if port == 443:
                context = ssl.create_default_context()
                context.check_hostname = False
                context.verify_mode = ssl.CERT_NONE
            conn = http.client.HTTPSConnection(ip, port, context=context, timeout=5) if port == 443 else http.client.HTTPConnection(ip, port, timeout=5)
            conn.putrequest(method, path, skip_host=True, skip_accept_encoding=True)
            conn.putheader("Host", f"{ip}:{port}")
            conn.putheader("User-Agent", "Mozilla/5.0")
            conn.putheader("Connection", "close")
            if data:
                conn.putheader("Content-Type", "application/x-www-form-urlencoded")
                conn.putheader("Content-Length", str(len(data)))
                conn.endheaders()
                conn.send(data.encode('utf-8') if isinstance(data, str) else data)
            else:
                conn.endheaders()
            res = conn.getresponse()
            return res.status, res.getheader('Server', ''), res.read().decode('utf-8', errors='ignore')
        except:
            return 0, "", ""

    @safe_operation("apache_verify")
    def verify_apache_vuln(self, target_ip, target_port=8080):
        if self.is_verified(target_ip, target_port):
            return True
            
        cache_key = f"{target_ip}:{target_port}"
        
